async function lsaSyncPermanentOutputs() {
  var statusEl = document.getElementById('lsaSyncStatus');
  if (statusEl) { statusEl.textContent = _t('adm_lsa_syncing'); statusEl.style.color = '#f97316'; }

  try {
    var { data, error } = await _cfStreamCall({ action: 'sync_permanent_outputs' });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    var msg = '';
    if (data.added && data.added.length > 0) msg += _t('adm_lsa_added') + ': ' + data.added.join(', ') + '. ';
    if (data.removed && data.removed.length > 0) msg += _t('adm_lsa_removed') + ': ' + data.removed.length + '. ';
    if (!msg) msg = _t('adm_lsa_all_synced') + ' — ' + (data.total_active || 0) + ' ' + _t('adm_lsa_active_dest') + '.';

    if (statusEl) { statusEl.textContent = msg; statusEl.style.color = '#22c55e'; }
  } catch (e) {
    console.error('[OBS Config] Sync error:', e);
    if (statusEl) { statusEl.textContent = 'Error: ' + (e.message || e); statusEl.style.color = '#ef4444'; }
  }
}

/* ── Resolve class_group → student emails for push notifications ── */
function lsaGetEmailsForGroup(classGroup) {
  // Get student groups from localStorage (admin has this from gatekeeper/zoom-recordings)
  var allStudents = [];
  try { allStudents = JSON.parse(localStorage.getItem('maestroac_student_groups') || '[]'); } catch(e) { console.warn('[LiveStreamAdmin]', e.message || e); }

  if (!classGroup || classGroup === 'todos') {
    // Return all student emails
    return allStudents.map(function(s) { return s.email; }).filter(Boolean);
  }

  // Map class_group to student group IDs
  var groupMap = {
    mar_mie: ['hibridos', 'hibridos_presencial', 'hibridos_enlinea', 'whatsapp_99', 'membresia_119', 'membresia_299', 'telegram'],
    sab_dom: ['trinidad', 'trinidad_presencial', 'trinidad_enlinea', 'whatsapp_299', 'membresia_299']
  };
  var targetGroups = groupMap[classGroup] || [];
  if (targetGroups.length === 0) return [];

  return allStudents.filter(function(s) {
    if (!s.groups || !s.email) return false;
    return targetGroups.some(function(g) { return s.groups.indexOf(g) !== -1; });
  }).map(function(s) { return s.email; });
}

function lsaNotifyGoLive(stream) {
  if (!stream) return;
  // Prevent duplicate notifications for same stream
  if (stream._notifSent) return;
  stream._notifSent = true;
  var groupEmails = lsaGetEmailsForGroup(stream.class_group);

  var groupLabels = { todos: _t('adm_lsa_grp_all', 'Todos'), mar_mie: _t('adm_lsa_grp_mar_mie', 'Mar/Mié'), sab_dom: _t('adm_lsa_grp_sab_dom', 'Sáb/Dom'), trinidad: _t('adm_lsa_grp_sab_dom', 'Sáb/Dom') };
  var groupLabel = groupLabels[stream.class_group] || _t('adm_lsa_grp_all', 'Todos');
  var pushTitle = '🔴 ' + _t('adm_lsa_live') + ': ' + (stream.title || _t('adm_lsa_class_live'));
  var pushBody = _t('adm_lsa_push_body_live', 'Maestro Mario está transmitiendo ahora. ¡Entra a ver la clase!');

  if (groupEmails.length > 0) {
    // Send push to group-specific students
    if (typeof notifyStudents === 'function') {
      notifyStudents(pushTitle, pushBody, 'clase', groupEmails);
    }
    console.log('[LiveStreamAdmin] Push sent to ' + groupEmails.length + ' students (' + groupLabel + ')');
  } else {
    // No group emails found — send to ALL active push subscribers automatically
    console.log('[LiveStreamAdmin] No group emails found, sending push to ALL subscribers');
    if (typeof notifyStudents === 'function') {
      notifyStudents(pushTitle, pushBody, 'clase', 'all');
    }
    console.log('[LiveStreamAdmin] Push sent to ALL students');
  }
}

/* ── Start stream (mark as live) ────────────────────────────── */
async function adminStartStream(streamId) {
  if (!confirm(_t('adm_lsa_confirm_mark_live'))) return;

  try {
    var { data, error } = await _cfStreamCall({ action: 'update_status', stream_id: streamId, new_status: 'live' });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    // Send push notification to students in this group
    var stream = _lsaStreams.find(function(s) { return s.id === streamId; });
    lsaNotifyGoLive(stream);

    loadAdminStreams();
  } catch (e) {
    console.error('[LiveStreamAdmin] Start error:', e);
    alert('Error: ' + (e.message || e));
  }
}

/* ── End stream ─────────────────────────────────────────────── */
async function adminEndStream(streamId) {
  if (!confirm(_t('adm_lsa_confirm_end'))) return;

  try {
    var { data, error } = await _cfStreamCall({ action: 'update_status', stream_id: streamId, new_status: 'ended' });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    loadAdminStreams();
  } catch (e) {
    console.error('[LiveStreamAdmin] End error:', e);
    alert('Error: ' + (e.message || e));
  }
}

/* ── Cancel stream ──────────────────────────────────────────── */
async function adminCancelStream(streamId) {
  if (!confirm(_t('adm_lsa_confirm_cancel'))) return;

  try {
    var { data, error } = await _cfStreamCall({ action: 'update_status', stream_id: streamId, new_status: 'cancelled' });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    loadAdminStreams();
  } catch (e) {
    console.error('[LiveStreamAdmin] Cancel error:', e);
    alert('Error: ' + (e.message || e));
  }
}

/* ── Delete stream + its recordings ─────────────────────────── */
async function adminDeleteStream(streamId) {
  if (!confirm(_t('adm_lsa_confirm_delete'))) return;

  console.log('[LiveStreamAdmin] Deleting stream:', streamId);
  try {
    var result = await _cfStreamCall({ action: 'delete_stream', stream_id: streamId });
    console.log('[LiveStreamAdmin] Delete result:', JSON.stringify(result));
    if (result.error) throw result.error;
    if (result.data && result.data.error) throw new Error(result.data.error + (result.data.details ? ': ' + result.data.details : ''));
    alert(_t('adm_lsa_stream_deleted', 'Stream eliminado exitosamente.'));
    loadAdminStreams();
  } catch (e) {
    console.error('[LiveStreamAdmin] Delete error:', e);
    alert(_t('adm_lsa_error_deleting') + ': ' + (e.message || e));
  }
}

/* ── Sync recordings ────────────────────────────────────────── */
async function adminSyncRecordings(streamId) {
  var stream = _lsaStreams.find(function(s) { return s.id === streamId; });
  if (!stream) return;

  try {
    var { data, error } = await _cfStreamCall({ action: 'sync_recordings', stream_id: streamId, cf_input_id: stream.cf_input_id, force: true });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    var msg = _t('adm_lsa_sync_complete', 'Sincronización completa: {n} grabación(es) nueva(s)').replace('{n}', (data.synced || 0));
    if (data.skipped) msg += ', ' + data.skipped + ' descartada(s) por tiempo';
    msg += ' de ' + (data.total_videos || 0) + ' video(s) totales.';
    alert(msg);
    loadAdminStreams();
    // Auto-show recordings panel
    setTimeout(function() { lsaLoadRecordingsForStream(streamId); }, 300);
  } catch (e) {
    console.error('[LiveStreamAdmin] Sync error:', e);
    alert(_t('adm_lsa_error_syncing') + ': ' + (e.message || e));
  }
}

/* ── Attendance Panel ──────────────────────────────────────── */
async function lsaShowAttendance(streamId) {
  // Toggle off if already open
  var oldPanel = document.getElementById('lsaAttendPanel_' + streamId);
  if (oldPanel) { oldPanel.remove(); return; }

  // Find the stream card
  var cards = document.querySelectorAll('#lsaStreamList .lsa-card');
  var targetCard = null;
  for (var i = 0; i < _lsaStreams.length; i++) {
    if (_lsaStreams[i].id === streamId && cards[i]) {
      targetCard = cards[i];
      break;
    }
  }
  if (!targetCard) return;

  var panel = document.createElement('div');
  panel.id = 'lsaAttendPanel_' + streamId;
  panel.style.cssText = 'background:#0f172a;border:1px solid rgba(14,165,233,0.4);border-radius:12px;padding:16px;margin-top:8px;margin-bottom:12px;max-height:80vh;overflow-y:auto;';
  panel.innerHTML = '<div style="color:#0ea5e9;font-weight:700;font-size:13px;">📊 ' + _t('adm_lsa_loading_attendance') + '</div>';
  targetCard.after(panel);

  try {
    // Get attendance data from stream_attendance table
    var { data: attendance, error } = await supabaseClient
      .from('stream_attendance')
      .select('*')
      .eq('stream_id', streamId)
      .order('joined_at', { ascending: true });

    if (error) throw error;

    // Get ALL chat messages (not just unique — for message count per person)
    var { data: chatMsgs } = await supabaseClient
      .from('stream_chat_messages')
      .select('user_email, user_name, created_at')
      .eq('stream_id', streamId)
      .order('created_at', { ascending: true });

    // Aggregate: unique students with their data
    var students = {};

    // From attendance log (future streams will have this)
    (attendance || []).forEach(function(a) {
      var key = a.student_email.toLowerCase().trim();
      if (!students[key]) {
        students[key] = { email: key, name: a.student_name || '', joined: a.joined_at, left: a.left_at, duration: 0, participated: false, source: a.source, visits: 0, msgCount: 0, firstSeen: a.joined_at };
      }
      students[key].visits++;
      if (a.participated) students[key].participated = true;
      if (a.left_at && a.joined_at) {
        students[key].duration += (new Date(a.left_at) - new Date(a.joined_at)) / 1000;
      }
      if (!students[key].firstSeen || new Date(a.joined_at) < new Date(students[key].firstSeen)) {
        students[key].firstSeen = a.joined_at;
      }
    });

    // From chat messages (for past streams, this is the primary data source)
    (chatMsgs || []).forEach(function(c) {
      var key = c.user_email.toLowerCase().trim();
      if (!students[key]) {
        students[key] = { email: key, name: c.user_name || '', joined: null, left: null, duration: 0, participated: false, source: 'chat', visits: 0, msgCount: 0, firstSeen: c.created_at };
      }
      students[key].msgCount++;
      students[key].chatted = true;
      if (!students[key].name && c.user_name) students[key].name = c.user_name;
      if (!students[key].firstSeen || new Date(c.created_at) < new Date(students[key].firstSeen)) {
        students[key].firstSeen = c.created_at;
      }
    });

    // Get emails for users lookup
    var emailList = Object.keys(students);

    // Lookup users table for phone numbers and full names
    var usersMap = {};
    if (emailList.length > 0) {
      // Query in batches of 50
      for (var b = 0; b < emailList.length; b += 50) {
        var batch = emailList.slice(b, b + 50);
        var _ud_usersData = await usersDataAdmin('admin_list', { filters: { email_in: batch }, fields: ['email','nombre','telefono'], limit: 100 });
        var usersData = _ud_usersData.data || [];

        (usersData || []).forEach(function(u) {
          usersMap[u.email.toLowerCase().trim()] = u;
        });
      }
    }

    // Enrich students with users data
    var studentList = Object.values(students);
    studentList.forEach(function(st) {
      var user = usersMap[st.email];
      if (user) {
        if (user.nombre && (!st.name || st.name === 'Estudiante')) st.name = user.nombre;
        st.telefono = user.telefono || '';
      } else {
        st.telefono = '';
      }
    });

    var liveCount = studentList.filter(function(s) { return s.source === 'live'; }).length;
    var vodCount = studentList.filter(function(s) { return s.source === 'vod'; }).length;
    var chatCount = studentList.filter(function(s) { return s.source === 'chat'; }).length;
    var hasAttendanceLog = (attendance || []).length > 0;

    var html = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">' +
      '<span style="color:#0ea5e9;font-weight:700;font-size:14px;">📊 Asistencia</span>' +
      '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'lsaAttendPanel_' + streamId + '\').remove()" style="font-size:11px;padding:4px 10px;">✕ Cerrar</button>' +
    '</div>';

    // Data source notice
    if (!hasAttendanceLog && chatCount > 0) {
      html += '<div style="background:rgba(251,191,36,0.1);border:1px solid rgba(251,191,36,0.3);border-radius:8px;padding:10px;margin-bottom:12px;color:#fbbf24;font-size:12px;">' +
        '⚠️ Esta clase fue antes del sistema de asistencia. Solo se muestran los <strong>' + chatCount + ' estudiantes que participaron en el chat</strong>. ' +
        _t('adm_lsa_no_chat_hint', 'Los que vieron sin chatear no aparecen. En futuras clases se capturará a todos automáticamente.') +
      '</div>';
    }

    // Stats row
    html += '<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:12px;">' +
      '<div style="background:#1e293b;border-radius:10px;padding:10px 16px;text-align:center;flex:1;min-width:80px;">' +
        '<div style="color:#22c55e;font-size:24px;font-weight:800;">' + studentList.length + '</div>' +
        '<div style="color:#64748b;font-size:11px;">Registrados</div>' +
      '</div>';
    if (hasAttendanceLog) {
      html +=
        '<div style="background:#1e293b;border-radius:10px;padding:10px 16px;text-align:center;flex:1;min-width:80px;">' +
          '<div style="color:#ef4444;font-size:24px;font-weight:800;">' + liveCount + '</div>' +
          '<div style="color:#64748b;font-size:11px;">En Vivo</div>' +
        '</div>' +
        '<div style="background:#1e293b;border-radius:10px;padding:10px 16px;text-align:center;flex:1;min-width:80px;">' +
          '<div style="color:#8b5cf6;font-size:24px;font-weight:800;">' + vodCount + '</div>' +
          '<div style="color:#64748b;font-size:11px;">VOD</div>' +
        '</div>';
    }
    html += '<div style="background:#1e293b;border-radius:10px;padding:10px 16px;text-align:center;flex:1;min-width:80px;">' +
        '<div style="color:#3b82f6;font-size:24px;font-weight:800;">' + (chatMsgs || []).length + '</div>' +
        '<div style="color:#64748b;font-size:11px;">Mensajes Chat</div>' +
      '</div>' +
    '</div>';

    if (studentList.length === 0) {
      html += '<div style="text-align:center;padding:16px;color:#64748b;font-size:13px;">' + _t('lsa_no_attendance','No hay registros de asistencia para este stream.') + '</div>';
    } else {
      // Search filter
      html += '<div style="margin-bottom:10px;"><input type="text" id="lsaAttendSearch_' + streamId + '" placeholder="🔍 Buscar estudiante..." oninput="lsaFilterAttendance(\'' + streamId + '\')" style="width:100%;padding:8px 12px;background:#1e293b;border:1px solid rgba(255,255,255,0.1);border-radius:8px;color:#e2e8f0;font-size:12px;outline:none;box-sizing:border-box;"></div>';

      // Student list table with name, email, phone
      html += '<div style="overflow-x:auto;max-height:50vh;overflow-y:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">' +
        '<thead style="position:sticky;top:0;background:#0f172a;z-index:1;"><tr style="border-bottom:1px solid rgba(255,255,255,0.1);">' +
          '<th style="text-align:left;padding:8px 4px;color:#94a3b8;font-weight:600;width:30px;">#</th>' +
          '<th style="text-align:left;padding:8px 4px;color:#94a3b8;font-weight:600;min-width:120px;">Nombre</th>' +
          '<th style="text-align:left;padding:8px 4px;color:#94a3b8;font-weight:600;min-width:140px;">Email</th>' +
          '<th style="text-align:left;padding:8px 4px;color:#94a3b8;font-weight:600;min-width:100px;">' + _t('adm_lsa_col_phone', 'Teléfono') + '</th>' +
          '<th style="text-align:center;padding:8px 4px;color:#94a3b8;font-weight:600;width:60px;">Hora</th>' +
          '<th style="text-align:center;padding:8px 4px;color:#94a3b8;font-weight:600;width:50px;">Msgs</th>' +
        '</tr></thead><tbody id="lsaAttendBody_' + streamId + '">';

      // Sort by first seen time, then by name
      studentList.sort(function(a, b) {
        if (a.firstSeen && b.firstSeen) return new Date(a.firstSeen) - new Date(b.firstSeen);
        if (a.firstSeen) return -1;
        if (b.firstSeen) return 1;
        return (a.name || '').localeCompare(b.name || '');
      });

      for (var j = 0; j < studentList.length; j++) {
        var st = studentList[j];
        var timeStr = st.firstSeen ? new Date(st.firstSeen).toLocaleTimeString('es-US', { hour: '2-digit', minute: '2-digit' }) : '—';

        html += '<tr class="lsa-attend-row" data-search="' + _lsaEsc((st.name || '').toLowerCase() + ' ' + st.email.toLowerCase()) + '" style="border-bottom:1px solid rgba(255,255,255,0.05);">' +
          '<td style="padding:6px 4px;color:#64748b;">' + (j + 1) + '</td>' +
          '<td style="padding:6px 4px;color:#e2e8f0;font-weight:600;word-break:break-word;">' + _lsaEsc(st.name || '—') + '</td>' +
          '<td style="padding:6px 4px;color:#94a3b8;word-break:break-all;font-size:11px;">' + _lsaEsc(st.email) + '</td>' +
          '<td style="padding:6px 4px;color:#94a3b8;">' + _lsaEsc(st.telefono || '—') + '</td>' +
          '<td style="padding:6px 4px;text-align:center;color:#94a3b8;">' + timeStr + '</td>' +
          '<td style="padding:6px 4px;text-align:center;color:' + (st.msgCount > 0 ? '#22c55e' : '#64748b') + ';font-weight:600;">' + (st.msgCount || 0) + '</td>' +
        '</tr>';
      }

      html += '</tbody></table></div>';
    }

    panel.innerHTML = html;

  } catch (e) {
    console.error('[LiveStreamAdmin] Attendance error:', e);
    panel.innerHTML = '<div style="color:#ef4444;font-size:13px;">' + _t('adm_lsa_error_loading_attendance', 'Error cargando asistencia:') + ' ' + _lsaEsc(e.message || String(e)) + '</div>' +
      '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'lsaAttendPanel_' + streamId + '\').remove()" style="margin-top:8px;font-size:11px;">✕ ' + _t('adm_lsa_close', 'Cerrar') + '</button>';
  }
}

/* ── Attendance search filter ───────────────────────────────── */
function lsaFilterAttendance(streamId) {
  var input = document.getElementById('lsaAttendSearch_' + streamId);
  if (!input) return;
  var query = input.value.toLowerCase().trim();
  var rows = document.querySelectorAll('#lsaAttendBody_' + streamId + ' .lsa-attend-row');
  rows.forEach(function(row) {
    var searchData = row.getAttribute('data-search') || '';
    row.style.display = !query || searchData.indexOf(query) !== -1 ? '' : 'none';
  });
}

/* ── Upload external recording ─────────────────────────────── */
function lsaUploadRecording(streamId) {
  // Show upload options dialog
  var cards = document.querySelectorAll('#lsaStreamList .lsa-card');
  var targetCard = null;
  for (var i = 0; i < _lsaStreams.length; i++) {
    if (_lsaStreams[i].id === streamId && cards[i]) { targetCard = cards[i]; break; }
  }

  var panelId = 'lsaUploadOpts_' + streamId;
  var old = document.getElementById(panelId);
  if (old) { old.remove(); return; }

  var panel = document.createElement('div');
  panel.id = panelId;
  panel.style.cssText = 'background:#0f172a;border:1px solid rgba(139,92,246,0.4);border-radius:12px;padding:16px;margin-top:8px;margin-bottom:12px;';
  panel.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">' +
      '<span style="color:#a78bfa;font-weight:700;font-size:14px;">📤 ' + _t('adm_lsa_upload_recording_label', 'Subir Grabación') + '</span>' +
      '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'' + panelId + '\').remove()" style="font-size:11px;padding:3px 8px;">✕</button>' +
    '</div>' +
    '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:12px;">' +
      '<button class="lsa-btn" onclick="lsaUploadFile(\'' + streamId + '\')" style="background:#8b5cf6;color:#fff;font-size:13px;padding:10px 20px;">📁 Subir Archivo</button>' +
      '<button class="lsa-btn" onclick="lsaShowUrlImport(\'' + streamId + '\')" style="background:#0ea5e9;color:#fff;font-size:13px;padding:10px 20px;">🔗 Importar desde URL</button>' +
    '</div>' +
    '<div id="lsaUploadArea_' + streamId + '"></div>';

  if (targetCard) { targetCard.after(panel); } else { document.getElementById('lsaStreamList').appendChild(panel); }
}

/* ── URL Import ───────────────────────────────────────────── */
function lsaShowUrlImport(streamId) {
  var area = document.getElementById('lsaUploadArea_' + streamId);
  if (!area) return;
  area.innerHTML =
    '<div style="color:#94a3b8;font-size:12px;margin-bottom:8px;">Pega la URL directa del video (Google Drive link directo, Dropbox, o cualquier link .mp4/.webm):</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<input type="text" id="lsaUrlInput_' + streamId + '" placeholder="https://..." style="flex:1;background:#1e293b;border:1px solid rgba(255,255,255,0.2);border-radius:8px;padding:8px 12px;color:#fff;font-size:13px;">' +
      '<button class="lsa-btn" onclick="lsaImportFromUrl(\'' + streamId + '\')" style="background:#0ea5e9;color:#fff;font-size:12px;">Importar</button>' +
    '</div>' +
    '<div id="lsaUrlStatus_' + streamId + '" style="margin-top:8px;font-size:12px;display:none;"></div>';
}

async function lsaImportFromUrl(streamId) {
  var urlInput = document.getElementById('lsaUrlInput_' + streamId);
  var statusEl = document.getElementById('lsaUrlStatus_' + streamId);
  if (!urlInput) return;

  var url = urlInput.value.trim();
  if (!url) { alert(_t('adm_lsa_paste_url', 'Pega una URL')); return; }
  if (!/^https?:\/\//i.test(url)) { alert(_t('adm_lsa_only_https', 'Solo URLs http/https permitidas')); return; }

  statusEl.style.display = '';
  statusEl.style.color = '#fbbf24';
  statusEl.textContent = '⏳ Enviando a Cloudflare...';

  try {
    var { data, error } = await _cfStreamCall({
      action: 'copy_from_url',
      url: url,
      stream_id: streamId,
      filename: url.split('/').pop() || 'import'
    });
    if (error) throw error;
    if (data.error) throw new Error(data.error + (data.details ? ' — ' + JSON.stringify(data.details) : ''));

    statusEl.style.color = '#22c55e';
    statusEl.textContent = '✅ ' + _t('lsa_video_imported','Video importado. Cloudflare lo está procesando') + ' (unos minutos)...';

    setTimeout(function() {
      var p = document.getElementById('lsaUploadOpts_' + streamId);
      if (p) p.remove();
      lsaLoadRecordingsForStream(streamId);
    }, 3000);
  } catch (e) {
    console.error('[LiveStreamAdmin] URL import error:', e);
    statusEl.style.color = '#ef4444';
    statusEl.textContent = '❌ Error: ' + (e.message || e);
  }
}

/* ── File Upload via Supabase Storage → Cloudflare copy ──── */
async function lsaUploadFile(streamId) {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'video/*,.mkv,.avi,.mov,.mp4,.webm,.ts';
  input.onchange = async function() {
    var file = input.files[0];
    if (!file) return;

    var sizeMB = (file.size / 1024 / 1024).toFixed(1);
    if (!confirm('Subir "' + file.name + '" (' + sizeMB + ' MB)?')) return;

    var area = document.getElementById('lsaUploadArea_' + streamId);
    if (!area) return;

    area.innerHTML =
      '<div style="color:#a78bfa;font-weight:700;font-size:13px;margin-bottom:8px;">📤 Subiendo...</div>' +
      '<div style="background:#1e293b;border-radius:8px;height:24px;overflow:hidden;position:relative;">' +
        '<div id="lsaUpBar_' + streamId + '" style="background:linear-gradient(90deg,#8b5cf6,#6366f1);height:100%;width:0%;transition:width 0.3s;border-radius:8px;"></div>' +
        '<span id="lsaUpPct_' + streamId + '" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:700;">0%</span>' +
      '</div>' +
      '<div id="lsaUpInfo_' + streamId + '" style="color:#64748b;font-size:11px;margin-top:6px;">Subiendo a servidor intermedio...</div>';

    var barEl = document.getElementById('lsaUpBar_' + streamId);
    var pctEl = document.getElementById('lsaUpPct_' + streamId);
    var infoEl = document.getElementById('lsaUpInfo_' + streamId);

    try {
      // Step 1: Upload to Supabase Storage (proper CORS)
      var storagePath = 'uploads/' + Date.now() + '_' + file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
      var sbUrl = (typeof SUPABASE_URL !== 'undefined') ? SUPABASE_URL : 'https://htklsowiyjwsjnacnvnr.supabase.co';
      var sbKey = (typeof SUPABASE_KEY !== 'undefined') ? SUPABASE_KEY : '';

      // Use XHR for progress tracking
      await new Promise(function(resolve, reject) {
        var xhr = new XMLHttpRequest();
        xhr.open('POST', sbUrl + '/storage/v1/object/stream-uploads/' + storagePath, true);
        xhr.setRequestHeader('Authorization', 'Bearer ' + sbKey);
        xhr.setRequestHeader('apikey', sbKey);
        xhr.setRequestHeader('Content-Type', file.type || 'application/octet-stream');
        xhr.setRequestHeader('x-upsert', 'true');

        xhr.upload.onprogress = function(e) {
          if (e.lengthComputable) {
            var pct = Math.round(e.loaded / e.total * 100);
            barEl.style.width = pct + '%';
            pctEl.textContent = pct + '%';
            var uploadedMB = (e.loaded / 1024 / 1024).toFixed(1);
            infoEl.textContent = uploadedMB + ' / ' + sizeMB + ' MB subidos a servidor';
          }
        };

        xhr.onload = function() {
          if (xhr.status >= 200 && xhr.status < 300) { resolve(); }
          else { reject(new Error('Storage upload failed: HTTP ' + xhr.status + ' ' + xhr.responseText)); }
        };
        xhr.onerror = function() { reject(new Error('Error de red subiendo a storage')); };
        xhr.send(file);
      });

      // Step 2: Get public URL
      barEl.style.width = '100%';
      pctEl.textContent = '100%';
      infoEl.textContent = 'Enviando a Cloudflare...';

      var publicUrl = sbUrl + '/storage/v1/object/public/stream-uploads/' + storagePath;

      // Step 3: Tell Cloudflare to copy from the public URL
      var { data, error } = await _cfStreamCall({
        action: 'copy_from_url',
        url: publicUrl,
        stream_id: streamId,
        filename: file.name
      });
      if (error) throw error;
      if (data.error) throw new Error(data.error + (data.details ? ' — ' + JSON.stringify(data.details) : ''));

      // Done! Do NOT delete from Storage yet — CF is still downloading!
      // Storage file will be cleaned up when user clicks "Verificar" and video is ready
      area.innerHTML = '<div style="color:#22c55e;font-weight:700;font-size:13px;">✅ ' + _t('lsa_recording_uploaded','Grabación subida exitosamente') + '</div>' +
        '<div style="color:#94a3b8;font-size:12px;margin-top:4px;">' + _t('adm_lsa_cloudflare_processing', 'Cloudflare está descargando y procesando el video (5-10 min). Usa "🔄 Verificar" después.') + '</div>';

      setTimeout(function() {
        var p = document.getElementById('lsaUploadOpts_' + streamId);
        if (p) p.remove();
        lsaLoadRecordingsForStream(streamId);
      }, 3000);

    } catch (e) {
      console.error('[LiveStreamAdmin] Upload error:', e);
      area.innerHTML = '<div style="color:#ef4444;font-weight:700;font-size:13px;">Error subiendo grabacion</div>' +
        '<div style="color:#f87171;font-size:12px;margin-top:4px;">' + _lsaEsc(e.message || String(e)) + '</div>';
    }
  };
  input.click();
}

/* ── Auto-upload recording → Supabase Storage (direct, inline-playable) ─ */
async function _lsaAutoUploadRecording(blob, streamId) {
  // Capture duration NOW before onstop handler resets _lsaRecStartTime
  var durationSec = _lsaRecStartTime ? Math.round((Date.now() - _lsaRecStartTime) / 1000) : null;
  var sizeMB = (blob.size / 1024 / 1024).toFixed(1);
  var segNum = (_lsaGDriveUploadQueue ? _lsaGDriveUploadQueue.length : 0) + 1;
  var mimeType = blob.type || _lsaRecMimeType || 'video/webm';
  var ext = (mimeType.indexOf('mp4') !== -1) ? '.mp4' : '.webm';
  var filename = 'clase-' + (streamId || 'unknown') + '-parte' + segNum + '-' + new Date().toISOString().slice(0,10) + ext;

  // Keep blob reference to prevent GC
  _lsaGDriveUploadBlob = blob;

  // ALWAYS use Supabase Storage — produces direct URLs that play inline
  // (Google Drive blocks iframe embedding via CSP, causing folder icon instead of video)
  console.log('[Studio] Uploading recording to Supabase Storage:', filename, sizeMB + 'MB');
  await _lsaUploadToSupabaseStorage(blob, streamId, durationSec, sizeMB, filename, mimeType);
}

/* ── Supabase Storage fallback upload (original logic) ── */
async function _lsaUploadToSupabaseStorage(blob, streamId, durationSec, sizeMB, filename, mimeType) {
  mimeType = mimeType || blob.type || _lsaRecMimeType || 'video/webm';
  var notif = document.createElement('div');
  notif.id = 'lsaAutoUploadNotif';
  notif.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:99999;background:#1e293b;border:2px solid #3b82f6;border-radius:14px;padding:18px 22px;width:340px;box-shadow:0 10px 40px rgba(0,0,0,0.5);';
  notif.innerHTML =
    '<div style="color:#e2e8f0;font-weight:700;font-size:14px;margin-bottom:10px;">📤 ' + _t('adm_lsa_uploading_recording', 'Subiendo grabación...') + '</div>' +
    '<div style="background:#0f172a;border-radius:6px;height:10px;overflow:hidden;margin-bottom:8px;">' +
      '<div id="lsaAutoUpBar" style="background:linear-gradient(90deg,#3b82f6,#6366f1);height:100%;width:0%;transition:width 0.3s;border-radius:6px;"></div>' +
    '</div>' +
    '<div id="lsaAutoUpText" style="color:#94a3b8;font-size:12px;">Preparando...</div>';
  document.body.appendChild(notif);

  var barEl = document.getElementById('lsaAutoUpBar');
  var textEl = document.getElementById('lsaAutoUpText');

  try {
    var storagePath = 'recordings/' + streamId + '/' + filename;
    var sbUrl = (typeof SUPABASE_URL !== 'undefined') ? SUPABASE_URL : 'https://htklsowiyjwsjnacnvnr.supabase.co';
    var sbKey = (typeof SUPABASE_KEY !== 'undefined') ? SUPABASE_KEY : '';

    if (textEl) textEl.textContent = 'Subiendo... (0 / ' + sizeMB + ' MB)';

    await new Promise(function(resolve, reject) {
      var xhr = new XMLHttpRequest();
      xhr.open('POST', sbUrl + '/storage/v1/object/stream-uploads/' + storagePath, true);
      xhr.setRequestHeader('Authorization', 'Bearer ' + sbKey);
      xhr.setRequestHeader('apikey', sbKey);
      xhr.setRequestHeader('Content-Type', mimeType);
      xhr.setRequestHeader('x-upsert', 'true');

      xhr.upload.onprogress = function(e) {
        if (e.lengthComputable) {
          var pct = Math.round(e.loaded / e.total * 100);
          if (barEl) barEl.style.width = pct + '%';
          var uploadedMB = (e.loaded / 1024 / 1024).toFixed(1);
          if (textEl) textEl.textContent = 'Subiendo... ' + uploadedMB + ' / ' + sizeMB + ' MB';
        }
      };

      xhr.onload = function() {
        if (xhr.status >= 200 && xhr.status < 300) resolve();
        else reject(new Error('Storage HTTP ' + xhr.status + ': ' + xhr.responseText));
      };
      xhr.onerror = function() { reject(new Error('Error de red')); };
      xhr.send(blob);
    });

    var publicUrl = sbUrl + '/storage/v1/object/public/stream-uploads/' + storagePath;
    if (barEl) barEl.style.width = '100%';
    if (textEl) textEl.textContent = 'Guardando en base de datos...';

    var { data: recData, error: recErr } = await supabaseClient
      .from('stream_recordings')
      .insert({
        stream_id: streamId,
        cf_video_uid: 'local-' + Date.now(),
        duration_seconds: durationSec,
        playback_url: publicUrl,
        download_url: publicUrl,
        status: 'ready',
        visible: false
      })
      .select()
      .single();

    if (recErr) throw new Error('DB error: ' + recErr.message);

    notif.style.borderColor = '#22c55e';
    notif.innerHTML =
      '<div style="color:#22c55e;font-weight:700;font-size:14px;">✅ ' + _t('adm_lsa_recording_saved', 'Grabación guardada') + '</div>' +
      '<div style="color:#94a3b8;font-size:12px;margin-top:6px;">' + _t('adm_lsa_size_label', 'Tamaño') + ': ' + sizeMB + ' MB' + (durationSec ? ' | ' + _t('adm_lsa_duration_label', 'Duración') + ': ' + Math.round(durationSec/60) + ' min' : '') + '<br>Oculta para estudiantes. Publícala cuando estés listo.</div>' +
      '<button onclick="this.parentNode.remove()" style="background:#475569;color:#fff;border:none;padding:6px 14px;border-radius:8px;cursor:pointer;font-size:12px;margin-top:10px;">OK</button>';
    setTimeout(function() { if (notif.parentNode) notif.remove(); }, 15000);
    loadAdminStreams();
    console.log('[Studio] Recording uploaded to Supabase Storage:', publicUrl);

  } catch(e) {
    console.error('[Studio] Supabase upload error:', e);
    notif.style.borderColor = '#ef4444';
    notif.innerHTML =
      '<div style="color:#ef4444;font-weight:700;font-size:14px;">❌ ' + _t('adm_lsa_error_uploading', 'Error subiendo grabación') + '</div>' +
      '<div style="color:#f87171;font-size:12px;margin-top:6px;">' + _lsaEsc(e.message || String(e)) + '</div>' +
      '<div style="color:#94a3b8;font-size:11px;margin-top:6px;">' + _t('adm_lsa_retry_next_class', 'Intenta grabar de nuevo en la próxima clase.') + '</div>' +
      '<button onclick="this.parentNode.remove()" style="background:#475569;color:#fff;border:none;padding:6px 14px;border-radius:8px;cursor:pointer;font-size:12px;margin-top:10px;">Cerrar</button>';
  }
}

/* ══════════════════════════════════════════════════════════════════
   GOOGLE DRIVE: OAuth + Upload Functions
   ══════════════════════════════════════════════════════════════════ */

/* ── Initialize Google Identity Services auth code client ── */
function _lsaGDriveInit() {
  if (_lsaGDriveCodeClient) return; // already initialized
  if (typeof google === 'undefined' || !google.accounts || !google.accounts.oauth2) {
    console.log('[GDrive] GIS not loaded yet — will retry on stream start');
    return;
  }
  if (typeof GOOGLE_CLIENT_ID === 'undefined' || !GOOGLE_CLIENT_ID) {
    console.log('[GDrive] No GOOGLE_CLIENT_ID configured — Drive upload disabled');
    return;
  }

  _lsaGDriveCodeClient = google.accounts.oauth2.initCodeClient({
    client_id: GOOGLE_CLIENT_ID,
    scope: (typeof GOOGLE_DRIVE_SCOPES !== 'undefined') ? GOOGLE_DRIVE_SCOPES : 'https://www.googleapis.com/auth/drive.file',
    ux_mode: 'popup',
    callback: _lsaGDriveOnCodeResponse,
  });

  // Restore cached token from localStorage
  try {
    var cached = localStorage.getItem('lsa_gdrive_token');
    if (cached) {
      var parsed = JSON.parse(cached);
      if (parsed.access_token && parsed.expires_at > Date.now()) {
        _lsaGDriveToken = parsed;
        _lsaGDriveUpdateIcon(true);
        console.log('[GDrive] Restored cached token (expires in ' + Math.round((parsed.expires_at - Date.now()) / 60000) + ' min)');
      }
    }
  } catch(e) { /* ignore corrupt cache */ }

  console.log('[GDrive] Initialized — ' + (_lsaGDriveToken ? 'connected' : 'not connected'));
}

/* ── Pending callback after GIS consent ── */
var _lsaGDrivePendingAuthCallback = null;

/* ── Handle auth code from Google consent popup ── */
async function _lsaGDriveOnCodeResponse(response) {
  if (response.error) {
    console.error('[GDrive] Auth error:', response.error);
    _lsaGDriveShowError(_t('adm_lsa_auth_error', 'Error de autenticación:') + ' ' + response.error);
    return;
  }

  try {
    var sbUrl = (typeof SUPABASE_URL !== 'undefined') ? SUPABASE_URL : 'https://htklsowiyjwsjnacnvnr.supabase.co';
    var sbKey = (typeof SUPABASE_KEY !== 'undefined') ? SUPABASE_KEY : '';
    var email = localStorage.getItem('tecnico_email') || 'admin';

    var res = await fetch(sbUrl + '/functions/v1/gdrive-token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + sbKey,
        'apikey': sbKey
      },
      body: JSON.stringify({
        action: 'exchange',
        code: response.code,
        admin_email: email,
        redirect_uri: window.location.origin
      })
    });

    var data = await res.json();
    if (!res.ok || data.error) throw new Error(data.error || 'Token exchange failed');

    _lsaGDriveToken = {
      access_token: data.access_token,
      expires_at: Date.now() + ((data.expires_in || 3600) * 1000) - 60000 // 1 min buffer
    };

    try { localStorage.setItem('lsa_gdrive_token', JSON.stringify(_lsaGDriveToken)); } catch(e) { console.warn('[LiveStreamAdmin]', e.message || e); }
    _lsaGDriveUpdateIcon(true);
    console.log('[GDrive] Connected successfully');

    // Execute pending callback (e.g., process upload queue)
    if (_lsaGDrivePendingAuthCallback) {
      var cb = _lsaGDrivePendingAuthCallback;
      _lsaGDrivePendingAuthCallback = null;
      cb();
    }

  } catch(e) {
    console.error('[GDrive] Token exchange error:', e);
    _lsaGDriveShowError('Error conectando con Google Drive: ' + e.message);
  }
}

/* ── Ensure valid token (auto-refresh if expired) ── */
async function _lsaGDriveEnsureToken() {
  // Already valid
  if (_lsaGDriveToken && _lsaGDriveToken.expires_at > Date.now()) {
    return _lsaGDriveToken.access_token;
  }

  // Try to refresh via Edge Function
  try {
    var sbUrl = (typeof SUPABASE_URL !== 'undefined') ? SUPABASE_URL : 'https://htklsowiyjwsjnacnvnr.supabase.co';
    var sbKey = (typeof SUPABASE_KEY !== 'undefined') ? SUPABASE_KEY : '';
    var email = localStorage.getItem('tecnico_email') || 'admin';

    var res = await fetch(sbUrl + '/functions/v1/gdrive-token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + sbKey,
        'apikey': sbKey
      },
      body: JSON.stringify({ action: 'refresh', admin_email: email })
    });

    var data = await res.json();
    if (!res.ok || data.error) throw new Error(data.error || 'Refresh failed');

    _lsaGDriveToken = {
      access_token: data.access_token,
      expires_at: Date.now() + ((data.expires_in || 3600) * 1000) - 60000
    };

    try { localStorage.setItem('lsa_gdrive_token', JSON.stringify(_lsaGDriveToken)); } catch(e) { console.warn('[LiveStreamAdmin]', e.message || e); }
    console.log('[GDrive] Token refreshed');
    return _lsaGDriveToken.access_token;

  } catch(e) {
    console.error('[GDrive] Token refresh failed:', e);
    _lsaGDriveToken = null;
    try { localStorage.removeItem('lsa_gdrive_token'); } catch(e2) { console.warn('[LiveStreamAdmin]', e2.message || e2); }
    _lsaGDriveUpdateIcon(false);
    return null;
  }
}

/* ── Trigger Google consent popup ── */
function _lsaGDriveRequestAuth(callback) {
  if (!_lsaGDriveCodeClient) {
    _lsaGDriveInit();
    if (!_lsaGDriveCodeClient) {
      console.error('[GDrive] Cannot init — GIS not loaded or no Client ID');
      return;
    }
  }
  _lsaGDrivePendingAuthCallback = callback || null;
  _lsaGDriveCodeClient.requestCode();
}

/* ── Find or create "MaestroAC Grabaciones" folder ── */
async function _lsaGDriveGetOrCreateFolder(token) {
  if (_lsaGDriveFolderId) return _lsaGDriveFolderId;

  var folderName = (typeof GOOGLE_DRIVE_FOLDER_NAME !== 'undefined') ? GOOGLE_DRIVE_FOLDER_NAME : 'MaestroAC Grabaciones';

  // Search for existing folder
  var q = encodeURIComponent("mimeType='application/vnd.google-apps.folder' and name='" + folderName + "' and trashed=false");
  var searchRes = await fetch('https://www.googleapis.com/drive/v3/files?q=' + q + '&fields=files(id,name)&pageSize=1', {
    headers: { 'Authorization': 'Bearer ' + token }
  });
  var searchData = await searchRes.json();

  if (searchData.files && searchData.files.length > 0) {
    _lsaGDriveFolderId = searchData.files[0].id;
    console.log('[GDrive] Found folder:', _lsaGDriveFolderId);
    return _lsaGDriveFolderId;
  }

  // Create folder
  var createRes = await fetch('https://www.googleapis.com/drive/v3/files', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + token,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      name: folderName,
      mimeType: 'application/vnd.google-apps.folder'
    })
  });
  var createData = await createRes.json();
  _lsaGDriveFolderId = createData.id;
  console.log('[GDrive] Created folder:', _lsaGDriveFolderId);
  return _lsaGDriveFolderId;
}

/* ── Resumable upload to Google Drive (10MB chunks) ── */
async function _lsaGDriveResumableUpload(blob, filename, token, folderId, onProgress) {
  var CHUNK_SIZE = 10 * 1024 * 1024; // 10MB
  var totalSize = blob.size;

  // Step 1: Initiate resumable upload session
  var initRes = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable', {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + token,
      'Content-Type': 'application/json; charset=UTF-8',
      'X-Upload-Content-Type': 'video/webm',
      'X-Upload-Content-Length': String(totalSize)
    },
    body: JSON.stringify({
      name: filename,
      mimeType: 'video/webm',
      parents: [folderId]
    })
  });

  if (!initRes.ok) {
    var errText = await initRes.text();
    throw new Error('Drive init failed (' + initRes.status + '): ' + errText);
  }

  var uploadUrl = initRes.headers.get('Location');
  if (!uploadUrl) throw new Error('No upload URL returned from Drive');

  // Step 2: Upload in chunks
  var offset = 0;
  var startTime = Date.now();
  var maxRetries = 5;

  while (offset < totalSize) {
    var end = Math.min(offset + CHUNK_SIZE, totalSize);
    var chunk = blob.slice(offset, end);
    var contentRange = 'bytes ' + offset + '-' + (end - 1) + '/' + totalSize;

    var success = false;
    var retries = 0;

    while (!success && retries < maxRetries) {
      try {
        // Refresh token if needed mid-upload
        var currentToken = await _lsaGDriveEnsureToken();
        if (!currentToken) throw new Error('No valid token — re-authorize Google Drive');

        var chunkRes = await fetch(uploadUrl, {
          method: 'PUT',
          headers: {
            'Content-Range': contentRange,
            'Content-Type': 'video/webm',
            'Authorization': 'Bearer ' + currentToken
          },
          body: chunk
        });

        // 200/201 = complete, 308 = more chunks needed
        if (chunkRes.status === 200 || chunkRes.status === 201) {
          var fileData = await chunkRes.json();
          if (onProgress) onProgress(totalSize, totalSize, startTime);
          return fileData; // Upload complete — return file metadata
        } else if (chunkRes.status === 308) {
          // Chunk accepted, continue
          var rangeHeader = chunkRes.headers.get('Range');
          if (rangeHeader) {
            // Parse "bytes=0-XXXX" to get confirmed offset
            var confirmedEnd = parseInt(rangeHeader.split('-')[1], 10) + 1;
            offset = confirmedEnd;
          } else {
            offset = end;
          }
          success = true;
        } else if (chunkRes.status === 401 || chunkRes.status === 403) {
          // Token expired mid-upload — force refresh
          _lsaGDriveToken = null;
          retries++;
          console.warn('[GDrive] Auth error during upload, refreshing token (retry ' + retries + ')');
        } else if (chunkRes.status >= 500) {
          // Server error — retry with exponential backoff
          retries++;
          var backoff = Math.min(1000 * Math.pow(2, retries), 30000);
          console.warn('[GDrive] Server error ' + chunkRes.status + ', retrying in ' + backoff + 'ms');
          await new Promise(function(r) { setTimeout(r, backoff); });
        } else {
          var errBody = await chunkRes.text();
          throw new Error('Chunk upload failed (' + chunkRes.status + '): ' + errBody);
        }
      } catch(e) {
        if (e.message && e.message.indexOf('Chunk upload failed') >= 0) throw e;
        retries++;
        if (retries >= maxRetries) throw new Error('Upload failed after ' + maxRetries + ' retries: ' + e.message);
        var backoff2 = Math.min(1000 * Math.pow(2, retries), 30000);
        console.warn('[GDrive] Network error, retry ' + retries + ' in ' + backoff2 + 'ms:', e.message);
        await new Promise(function(r) { setTimeout(r, backoff2); });
      }
    }

    if (onProgress) onProgress(offset, totalSize, startTime);
  }

  throw new Error('Upload completed but no final response received');
}

/* ── Sequential queue processor for multi-segment uploads ── */
async function _lsaGDriveProcessQueue() {
  if (_lsaGDriveUploading || _lsaGDriveUploadQueue.length === 0) return;
  _lsaGDriveUploading = true;

  while (_lsaGDriveUploadQueue.length > 0) {
    var item = _lsaGDriveUploadQueue[0];

    try {
      // Ensure valid token
      var token = await _lsaGDriveEnsureToken();
      if (!token) {
        // Need re-auth — show prompt and stop processing
        _lsaGDriveShowAuthPrompt(function() { _lsaGDriveProcessQueue(); });
        _lsaGDriveUploading = false;
        return;
      }

      // Get or create folder
      var folderId = await _lsaGDriveGetOrCreateFolder(token);

      // Show progress modal
      _lsaGDriveShowUploadModal(item.filename, item.sizeMB);

      // Upload with progress callback
      var fileData = await _lsaGDriveResumableUpload(
        item.blob, item.filename, token, folderId,
        function(loaded, total, startTime) {
          _lsaGDriveUpdateProgress(loaded, total, startTime);
        }
      );

      var driveUrl = 'https://drive.google.com/file/d/' + fileData.id + '/preview';
      console.log('[GDrive] Upload complete:', driveUrl);

      // Save metadata to stream_recordings
      var { error: recErr } = await supabaseClient
        .from('stream_recordings')
        .insert({
          stream_id: item.streamId,
          cf_video_uid: 'gdrive-' + fileData.id,
          duration_seconds: item.durationSec,
          playback_url: driveUrl,
          download_url: 'https://drive.google.com/uc?export=download&id=' + fileData.id,
          status: 'ready',
          visible: false
        });

      if (recErr) console.error('[GDrive] DB save error (non-fatal):', recErr.message);

      // Show success
      _lsaGDriveShowSuccess(driveUrl, item.sizeMB, item.durationSec);

      // Remove from queue
      _lsaGDriveUploadQueue.shift();

      // Release blob reference
      if (_lsaGDriveUploadQueue.length === 0) _lsaGDriveUploadBlob = null;

      // Reload recordings panel
      loadAdminStreams();

    } catch(e) {
      console.error('[GDrive] Upload error:', e);
      _lsaGDriveShowError(e.message, item.blob, item.filename);
      // Don't remove from queue — user can retry
      _lsaGDriveUploading = false;
      return;
    }
  }

  _lsaGDriveUploading = false;
}

/* ══════════════════════════════════════════════════════════════════
   GOOGLE DRIVE: Upload Progress UI
   ══════════════════════════════════════════════════════════════════ */

/* ── Progress modal (bottom-right card) ── */
function _lsaGDriveShowUploadModal(filename, sizeMB) {
  var existing = document.getElementById('lsaGDriveModal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'lsaGDriveModal';
  modal.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:99999;background:#1e293b;border:2px solid #4285f4;border-radius:14px;padding:18px 22px;width:360px;box-shadow:0 10px 40px rgba(0,0,0,0.5);';
  modal.innerHTML =
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">' +
      '<span style="font-size:20px;">☁️</span>' +
      '<div style="color:#e2e8f0;font-weight:700;font-size:14px;">Subiendo a Google Drive</div>' +
    '</div>' +
    '<div style="color:#94a3b8;font-size:11px;margin-bottom:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="' + _lsaEsc(filename) + '">' + _lsaEsc(filename) + ' (' + sizeMB + ' MB)</div>' +
    '<div style="background:#0f172a;border-radius:6px;height:10px;overflow:hidden;margin-bottom:8px;">' +
      '<div id="lsaGDriveBar" style="background:linear-gradient(90deg,#4285f4,#34a853);height:100%;width:0%;transition:width 0.3s;border-radius:6px;"></div>' +
    '</div>' +
    '<div id="lsaGDriveText" style="color:#94a3b8;font-size:12px;">Iniciando subida...</div>';
  document.body.appendChild(modal);
}

/* ── Live progress updates ── */
function _lsaGDriveUpdateProgress(loaded, total, startTime) {
  var barEl = document.getElementById('lsaGDriveBar');
  var textEl = document.getElementById('lsaGDriveText');
  if (!barEl || !textEl) return;

  var pct = Math.round(loaded / total * 100);
  barEl.style.width = pct + '%';

  var elapsed = (Date.now() - startTime) / 1000;
  var speed = elapsed > 0 ? loaded / elapsed : 0;
  var remaining = speed > 0 ? (total - loaded) / speed : 0;

  var speedText = speed > 1048576 ? (speed / 1048576).toFixed(1) + ' MB/s' : (speed / 1024).toFixed(0) + ' KB/s';
  var etaText = remaining < 60 ? Math.round(remaining) + 's' : Math.round(remaining / 60) + 'min';
  var loadedMB = (loaded / 1048576).toFixed(1);
  var totalMB = (total / 1048576).toFixed(1);

  textEl.textContent = pct + '% — ' + loadedMB + '/' + totalMB + ' MB — ' + speedText + ' — ' + etaText + ' restante';
}

/* ── Auth prompt modal (first-time connection) ── */
function _lsaGDriveShowAuthPrompt(callback) {
  var existing = document.getElementById('lsaGDriveModal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'lsaGDriveModal';
  modal.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:99999;background:#1e293b;border:2px solid #4285f4;border-radius:14px;padding:22px;width:360px;box-shadow:0 10px 40px rgba(0,0,0,0.5);';
  modal.innerHTML =
    '<div style="text-align:center;">' +
      '<span style="font-size:40px;display:block;margin-bottom:10px;">☁️</span>' +
      '<div style="color:#e2e8f0;font-weight:700;font-size:16px;margin-bottom:6px;">Conectar Google Drive</div>' +
      '<div style="color:#94a3b8;font-size:12px;margin-bottom:16px;">' + _t('adm_lsa_recording_ready_gdrive', 'Tu grabación está lista. Conecta tu Google Drive para subirla automáticamente.') + '</div>' +
      '<button id="lsaGDriveAuthBtn" style="width:100%;padding:12px;border:none;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;background:linear-gradient(135deg,#4285f4,#34a853);color:white;margin-bottom:8px;">Conectar con Google</button>' +
      '<button id="lsaGDriveSkipBtn" style="width:100%;padding:10px;border:none;border-radius:10px;font-size:12px;cursor:pointer;background:rgba(255,255,255,0.1);color:#94a3b8;">Descargar archivo sin subir</button>' +
    '</div>';
  document.body.appendChild(modal);

  document.getElementById('lsaGDriveAuthBtn').onclick = function() {
    this.textContent = 'Abriendo ventana de Google...';
    this.disabled = true;
    _lsaGDriveRequestAuth(callback);
  };

  document.getElementById('lsaGDriveSkipBtn').onclick = function() {
    // Download the first queued blob locally
    if (_lsaGDriveUploadQueue.length > 0) {
      _lsaGDriveDownloadLocal(_lsaGDriveUploadQueue[0].blob, _lsaGDriveUploadQueue[0].filename);
      _lsaGDriveUploadQueue.shift();
    }
    modal.remove();
  };
}

/* ── Success card ── */
function _lsaGDriveShowSuccess(driveUrl, sizeMB, durationSec) {
  var existing = document.getElementById('lsaGDriveModal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'lsaGDriveModal';
  modal.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:99999;background:#1e293b;border:2px solid #22c55e;border-radius:14px;padding:18px 22px;width:360px;box-shadow:0 10px 40px rgba(0,0,0,0.5);';
  modal.innerHTML =
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">' +
      '<span style="font-size:22px;">✅</span>' +
      '<div style="color:#22c55e;font-weight:700;font-size:14px;">' + _t('adm_lsa_recording_in_gdrive', 'Grabación en Google Drive') + '</div>' +
    '</div>' +
    '<div style="color:#94a3b8;font-size:12px;margin-bottom:12px;">' + _t('adm_lsa_size_label', 'Tamaño') + ': ' + sizeMB + ' MB' + (durationSec ? ' | ' + _t('adm_lsa_duration_label', 'Duración') + ': ' + Math.round(durationSec / 60) + ' min' : '') + '<br>Oculta para estudiantes. Publícala cuando estés listo.</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<a href="' + _lsaEsc(driveUrl) + '" target="_blank" rel="noopener" style="flex:1;display:block;padding:10px;border:none;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;background:#4285f4;color:white;text-decoration:none;text-align:center;">Abrir en Drive</a>' +
      '<button onclick="this.closest(\'#lsaGDriveModal\').remove()" style="flex:1;padding:10px;border:none;border-radius:8px;font-size:12px;cursor:pointer;background:#475569;color:white;">OK</button>' +
    '</div>';
  document.body.appendChild(modal);

  // Auto-dismiss after 20 seconds
  setTimeout(function() { if (modal.parentNode) modal.remove(); }, 20000);
}

/* ── Error card with retry + download fallback ── */
function _lsaGDriveShowError(message, blob, filename) {
  var existing = document.getElementById('lsaGDriveModal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'lsaGDriveModal';
  modal.style.cssText = 'position:fixed;bottom:20px;right:20px;z-index:99999;background:#1e293b;border:2px solid #ef4444;border-radius:14px;padding:18px 22px;width:360px;box-shadow:0 10px 40px rgba(0,0,0,0.5);';
  modal.innerHTML =
    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">' +
      '<span style="font-size:22px;">❌</span>' +
      '<div style="color:#ef4444;font-weight:700;font-size:14px;">Error subiendo a Drive</div>' +
    '</div>' +
    '<div style="color:#f87171;font-size:12px;margin-bottom:12px;word-break:break-word;">' + _lsaEsc(message || 'Error desconocido') + '</div>' +
    '<div style="display:flex;gap:8px;">' +
      '<button id="lsaGDriveRetryBtn" style="flex:1;padding:10px;border:none;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;background:#f59e0b;color:white;">Reintentar</button>' +
      '<button id="lsaGDriveDownloadBtn" style="flex:1;padding:10px;border:none;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;background:#6366f1;color:white;">Descargar .webm</button>' +
    '</div>' +
    '<button onclick="this.closest(\'#lsaGDriveModal\').remove()" style="width:100%;padding:8px;border:none;border-radius:8px;font-size:11px;cursor:pointer;background:rgba(255,255,255,0.1);color:#94a3b8;margin-top:8px;">Cerrar</button>';
  document.body.appendChild(modal);

  document.getElementById('lsaGDriveRetryBtn').onclick = function() {
    modal.remove();
    _lsaGDriveProcessQueue();
  };

  document.getElementById('lsaGDriveDownloadBtn').onclick = function() {
    if (blob) {
      _lsaGDriveDownloadLocal(blob, filename);
    } else if (_lsaGDriveUploadQueue.length > 0) {
      _lsaGDriveDownloadLocal(_lsaGDriveUploadQueue[0].blob, _lsaGDriveUploadQueue[0].filename);
    }
  };
}

/* ── Emergency local download (recording never lost) ── */
function _lsaGDriveDownloadLocal(blob, filename) {
  if (!blob) { console.error('[GDrive] No blob to download'); return; }
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = filename || 'grabacion-' + Date.now() + '.webm';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(function() { URL.revokeObjectURL(url); }, 5000);
  console.log('[GDrive] Emergency download triggered:', filename);
}

/* ── Update Drive icon in control bar ── */
function _lsaGDriveUpdateIcon(connected) {
  var icon = document.getElementById('lsaBtnGDrive');
  if (!icon) return;
  var dot = icon.querySelector('.lsa-gdrive-dot');
  if (dot) {
    dot.style.background = connected ? '#22c55e' : '#ef4444';
  }
  icon.title = connected ? 'Google Drive conectado' : 'Google Drive no conectado (click para conectar)';
}

/* ── Post-upload monitoring: verify CF processing succeeded ── */
function _lsaMonitorUploadStatus(recId, cfUid, streamId) {
  var checks = 0;
  var maxChecks = 10; // 10 checks × 2 min = 20 min max
  var interval = setInterval(async function() {
    checks++;
    try {
      var { data, error } = await _cfStreamCall({
        action: 'check_video_status',
        recording_id: recId,
        cf_video_uid: cfUid
      });
      if (error) { console.warn('[Studio] Upload monitor error:', error); return; }

      if (data.status === 'ready') {
        clearInterval(interval);
        console.log('[Studio] Upload confirmed ready:', cfUid);
        _lsChatToast2('✅ ' + _t('adm_lsa_recording_processed_cf', 'Grabación procesada correctamente en Cloudflare'), 'success');
        // Reload recordings panel if open
        if (streamId) lsaLoadRecordingsForStream(streamId);
        return;
      }

      if (data.status === 'error') {
        clearInterval(interval);
        console.error('[Studio] CF PROCESSING FAILED for:', cfUid);
        // Critical alert — user needs to know
        var alertNotif = document.createElement('div');
        alertNotif.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:999999;' +
          'background:#1e293b;border:3px solid #ef4444;border-radius:16px;padding:24px;width:420px;' +
          'box-shadow:0 20px 60px rgba(0,0,0,0.7);text-align:center;';
        alertNotif.innerHTML =
          '<div style="font-size:48px;margin-bottom:12px;">⚠️</div>' +
          '<div style="color:#ef4444;font-weight:700;font-size:16px;margin-bottom:8px;">' + _t('adm_lsa_recording_failed_cf', 'Grabación falló en Cloudflare') + '</div>' +
          '<div style="color:#94a3b8;font-size:13px;margin-bottom:16px;">' +
            _t('adm_lsa_cf_failed_desc', 'El video se subió pero Cloudflare no pudo procesarlo.<br>Tu copia local (.webm) fue descargada automáticamente.<br>Puedes re-subirla desde "Subir Grabación".') +
          '</div>' +
          '<button onclick="this.parentNode.remove()" style="background:#ef4444;color:#fff;border:none;padding:10px 24px;border-radius:10px;cursor:pointer;font-size:14px;font-weight:600;">' + _t('adm_lsa_understood', 'Entendido') + '</button>';
        document.body.appendChild(alertNotif);
        return;
      }

      // Still processing — continue checking
      if (checks >= maxChecks) {
        clearInterval(interval);
        console.warn('[Studio] Upload monitor timeout after', maxChecks, 'checks');
      }
    } catch(e) {
      console.warn('[Studio] Upload monitor exception:', e);
    }
  }, 120000); // Check every 2 minutes
}

/* ── Check if uploaded video finished processing ──────────── */
async function lsaCheckUploadStatus(recId, cfUid, streamId) {
  try {
    // Ask CF for video status via the edge function
    var { data, error } = await _cfStreamCall({
      action: 'check_video_status',
      recording_id: recId,
      cf_video_uid: cfUid
    });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    if (data.status === 'ready') {
      alert('✅ Video listo! Ya puedes publicarlo.');
    } else {
      alert('⏳ ' + _t('adm_lsa_still_processing', 'Todavía procesando. Intenta de nuevo en unos minutos.\nEstado:') + ' ' + (data.status || _t('adm_lsa_unknown', 'desconocido')));
    }
    lsaLoadRecordingsForStream(streamId);
  } catch (e) {
    console.error('[LiveStreamAdmin] Check status error:', e);
    alert('Error verificando: ' + (e.message || e));
  }
}

/* ── Trim / Clip panel ─────────────────────────────────────── */
function _lsaFmtTime(totalSec) {
  totalSec = Number(totalSec) || 0;
  var h = Math.floor(totalSec / 3600);
  var m = Math.floor((totalSec % 3600) / 60);
  var s = Math.floor(totalSec % 60);
  return (h > 0 ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function _lsaParseTime(str) {
  if (!str) return 0;
  var parts = str.split(':').map(Number);
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  return Number(parts[0]) || 0;
}

function lsaShowTrimPanel(recId, cfUid, streamId, durationSec, playbackUrl) {
  // Toggle off if already open
  var oldTrim = document.getElementById('lsaTrimPanel_' + recId);
  if (oldTrim) { oldTrim.remove(); return; }

  var recStatus = document.getElementById('lsaRecStatus_' + recId);
  var parentDiv = recStatus ? recStatus.parentElement : null;
  if (!parentDiv) return;

  var maxDur = Math.max(durationSec || 0, 1);

  var panel = document.createElement('div');
  panel.id = 'lsaTrimPanel_' + recId;
  panel.style.cssText = 'background:#0f172a;border:1px solid rgba(249,115,22,0.4);border-radius:10px;padding:14px;margin-top:10px;';

  panel.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">' +
      '<span style="color:#f97316;font-weight:700;font-size:13px;">✂ Recortar Video</span>' +
      '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'lsaTrimPanel_' + recId + '\').remove()" style="font-size:11px;padding:3px 8px;">✕</button>' +
    '</div>' +
    '<div style="color:#94a3b8;font-size:12px;margin-bottom:10px;">Duración total: <strong style="color:#fff;">' + _lsaFmtTime(maxDur) + '</strong> — Selecciona inicio y fin del clip</div>' +

    // Start time
    '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px;">' +
      '<label style="color:#94a3b8;font-size:12px;min-width:45px;">Inicio:</label>' +
      '<input type="range" id="lsaTrimStart_' + recId + '" min="0" max="' + maxDur + '" value="0" step="1" style="flex:1;min-width:120px;accent-color:#f97316;">' +
      '<span id="lsaTrimStartVal_' + recId + '" style="color:#fff;font-size:12px;font-weight:700;min-width:50px;">00:00</span>' +
      '<input type="text" id="lsaTrimStartTxt_' + recId + '" placeholder="0:00" style="width:55px;background:#1e293b;border:1px solid rgba(255,255,255,0.2);border-radius:6px;padding:4px 6px;color:#fff;font-size:11px;text-align:center;">' +
    '</div>' +

    // End time
    '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px;">' +
      '<label style="color:#94a3b8;font-size:12px;min-width:45px;">Fin:</label>' +
      '<input type="range" id="lsaTrimEnd_' + recId + '" min="0" max="' + maxDur + '" value="' + maxDur + '" step="1" style="flex:1;min-width:120px;accent-color:#f97316;">' +
      '<span id="lsaTrimEndVal_' + recId + '" style="color:#fff;font-size:12px;font-weight:700;min-width:50px;">' + _lsaFmtTime(maxDur) + '</span>' +
      '<input type="text" id="lsaTrimEndTxt_' + recId + '" placeholder="' + _lsaFmtTime(maxDur) + '" style="width:55px;background:#1e293b;border:1px solid rgba(255,255,255,0.2);border-radius:6px;padding:4px 6px;color:#fff;font-size:11px;text-align:center;">' +
    '</div>' +

    // Clip duration
    '<div id="lsaTrimDuration_' + recId + '" style="color:#64748b;font-size:11px;margin-bottom:10px;">Clip: ' + _lsaFmtTime(maxDur) + '</div>' +

    // Buttons
    '<div style="display:flex;gap:8px;">' +
      '<button class="lsa-btn" onclick="lsaCreateClip(\'' + recId + '\',\'' + cfUid + '\',\'' + streamId + '\')" style="background:#f97316;color:#fff;font-size:12px;font-weight:700;">✂ Crear Clip</button>' +
      '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'lsaTrimPanel_' + recId + '\').remove()" style="font-size:12px;">Cancelar</button>' +
    '</div>' +
    '<div id="lsaTrimStatus_' + recId + '" style="color:#94a3b8;font-size:12px;margin-top:8px;display:none;"></div>';

  parentDiv.appendChild(panel);

  // Wire up slider/text sync
  var startSlider = document.getElementById('lsaTrimStart_' + recId);
  var endSlider = document.getElementById('lsaTrimEnd_' + recId);
  var startVal = document.getElementById('lsaTrimStartVal_' + recId);
  var endVal = document.getElementById('lsaTrimEndVal_' + recId);
  var startTxt = document.getElementById('lsaTrimStartTxt_' + recId);
  var endTxt = document.getElementById('lsaTrimEndTxt_' + recId);
  var durDisplay = document.getElementById('lsaTrimDuration_' + recId);

  function updateDur() {
    var s = Number(startSlider.value);
    var e = Number(endSlider.value);
    var d = Math.max(0, e - s);
    durDisplay.textContent = 'Clip: ' + _lsaFmtTime(d) + (d < 5 ? ' ⚠️ Muy corto' : '');
    durDisplay.style.color = d < 5 ? '#ef4444' : '#64748b';
  }
  startSlider.addEventListener('input', function() { startVal.textContent = _lsaFmtTime(this.value); updateDur(); });
  endSlider.addEventListener('input', function() { endVal.textContent = _lsaFmtTime(this.value); updateDur(); });
  startTxt.addEventListener('input', function() {
    var s = _lsaParseTime(this.value);
    if (s >= 0 && s <= maxDur) { startSlider.value = s; startVal.textContent = _lsaFmtTime(s); updateDur(); }
  });
  endTxt.addEventListener('input', function() {
    var s = _lsaParseTime(this.value);
    if (s >= 0 && s <= maxDur) { endSlider.value = s; endVal.textContent = _lsaFmtTime(s); updateDur(); }
  });
}

async function lsaCreateClip(recId, cfUid, streamId) {
  var startEl = document.getElementById('lsaTrimStart_' + recId);
  var endEl = document.getElementById('lsaTrimEnd_' + recId);
  var statusEl = document.getElementById('lsaTrimStatus_' + recId);
  if (!startEl || !endEl) return;

  var startTime = Number(startEl.value);
  var endTime = Number(endEl.value);

  if (endTime <= startTime) { alert('El tiempo final debe ser mayor que el inicial'); return; }
  if (endTime - startTime < 5) { alert('El clip debe tener al menos 5 segundos'); return; }

  if (!confirm('Crear clip de ' + _lsaFmtTime(startTime) + ' a ' + _lsaFmtTime(endTime) + ' (' + _lsaFmtTime(endTime - startTime) + ')?')) return;

  if (statusEl) { statusEl.style.display = ''; statusEl.style.color = '#fbbf24'; statusEl.textContent = '⏳ Creando clip en Cloudflare...'; }

  try {
    var { data, error } = await _cfStreamCall({
      action: 'create_clip',
      stream_id: streamId,
      cf_video_uid: cfUid,
      start_time: startTime,
      end_time: endTime
    });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    if (statusEl) {
      statusEl.style.color = '#22c55e';
      statusEl.textContent = '✅ Clip creado (' + _lsaFmtTime(data.duration || (endTime - startTime)) + '). Procesando...';
    }

    setTimeout(function() {
      var tp = document.getElementById('lsaTrimPanel_' + recId);
      if (tp) tp.remove();
      lsaLoadRecordingsForStream(streamId);
    }, 2000);

  } catch (e) {
    console.error('[LiveStreamAdmin] Clip error:', e);
    if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.textContent = '❌ Error: ' + (e.message || e); }
  }
}

/* ===================================================================
   Recording Management Panel — Preview, publish, delete, download,
   transcribe, and generate quizzes for stream recordings.
   =================================================================== */

var _LSA_AI_URL = (typeof INSTRUCTOR_AI_URL !== 'undefined')
  ? INSTRUCTOR_AI_URL
  : 'https://htklsowiyjwsjnacnvnr.supabase.co/functions/v1/instructor-ai-chat';
var _LSA_TRANSCRIBE_URL = 'https://htklsowiyjwsjnacnvnr.supabase.co/functions/v1/transcribe-video';

/* ── Load recordings for a stream ──────────────────────────── */
async function lsaLoadRecordingsForStream(streamId) {
  try {
    var { data, error } = await supabaseClient
      .from('stream_recordings')
      .select('*')
      .eq('stream_id', streamId)
      .order('created_at', { ascending: true });

    if (error) throw error;
    lsaRenderRecordingsPanel(streamId, data || []);
  } catch (e) {
    console.error('[LiveStreamAdmin] Load recordings error:', e);
    alert(_t('adm_lsa_error_loading_recs') + ': ' + (e.message || e));
  }
}

/* ── Render recordings panel ───────────────────────────────── */
function lsaRenderRecordingsPanel(streamId, recordings) {
  // Remove existing panel
  var old = document.getElementById('lsaRecPanel_' + streamId);
  if (old) old.remove();

  // Find the stream card — the cards are in #lsaStreamList
  var cards = document.querySelectorAll('#lsaStreamList .lsa-card');
  var targetCard = null;
  for (var i = 0; i < _lsaStreams.length; i++) {
    if (_lsaStreams[i].id === streamId && cards[i]) {
      targetCard = cards[i];
      break;
    }
  }
  if (!targetCard) return;

  var panel = document.createElement('div');
  panel.id = 'lsaRecPanel_' + streamId;
  panel.style.cssText = 'background:#0f172a;border:1px solid rgba(59,130,246,0.3);border-radius:12px;padding:16px;margin-top:8px;margin-bottom:12px;';

  if (recordings.length === 0) {
    panel.innerHTML = '<div style="text-align:center;padding:20px;color:#64748b;font-size:13px;">' + _t('lsa_no_synced_recordings','No hay grabaciones sincronizadas para este stream.') + '</div>';
    targetCard.after(panel);
    return;
  }

  var html = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">' +
    '<span style="color:#3b82f6;font-weight:700;font-size:14px;">📂 Grabaciones (' + recordings.length + ')</span>' +
    '<button class="lsa-btn lsa-btn-gray" onclick="document.getElementById(\'lsaRecPanel_' + streamId + '\').remove()" style="font-size:11px;padding:4px 10px;">✕ Cerrar</button>' +
  '</div>';

  for (var j = 0; j < recordings.length; j++) {
    var r = recordings[j];
    var dur = r.duration_seconds ? Math.round(r.duration_seconds / 60) + ' min' : '—';
    var date = r.cf_created_at ? new Date(r.cf_created_at).toLocaleString('es-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) :
               new Date(r.created_at).toLocaleString('es-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    var visBadge = r.visible
      ? '<span style="background:rgba(34,197,94,0.2);color:#22c55e;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Visible</span>'
      : '<span style="background:rgba(239,68,68,0.2);color:#ef4444;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Oculto</span>';
    var freeBadge = r.is_free
      ? '<span style="background:rgba(34,197,94,0.15);color:#22c55e;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Gratis</span>'
      : '<span style="background:rgba(234,179,8,0.15);color:#eab308;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Membresía</span>';
    var transcriptBadge = r.transcript
      ? '<span style="background:rgba(139,92,246,0.15);color:#a78bfa;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Transcripción</span>'
      : '';
    var quizBadge = r.quiz_questions
      ? '<span style="background:rgba(59,130,246,0.15);color:#60a5fa;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">Quiz</span>'
      : '';
    var processingBadge = r.status === 'processing'
      ? '<span style="background:rgba(251,191,36,0.2);color:#fbbf24;padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;">⏳ Procesando</span>'
      : '';

    html += '<div style="background:#1e293b;border:1px solid rgba(255,255,255,0.1);border-radius:10px;padding:12px;margin-bottom:10px;">';

    // Processing notice
    if (r.status === 'processing') {
      html += '<div style="background:rgba(251,191,36,0.1);border:1px solid rgba(251,191,36,0.3);border-radius:8px;padding:10px;margin-bottom:10px;color:#fbbf24;font-size:12px;">' +
        '⏳ Video procesándose en Cloudflare. Espera unos minutos y haz clic en "🔄 Verificar" para actualizar el estado.' +
        '<button class="lsa-btn" onclick="lsaCheckUploadStatus(\'' + r.id + '\',\'' + (r.cf_video_uid || '') + '\',\'' + streamId + '\')" style="margin-left:8px;font-size:11px;background:#fbbf24;color:#000;padding:3px 10px;">🔄 Verificar</button>' +
      '</div>';
    }

    // Preview (video element for .webm/storage, Drive embed for gdrive, iframe for Cloudflare)
    if (r.playback_url && r.status !== 'processing') {
      var _pUrl = r.playback_url;
      var _isWebm = /\.(webm|mp4|mov)(\?|$)/i.test(_pUrl) || _pUrl.indexOf('/storage/') !== -1;
      var _isDrive = _pUrl.indexOf('drive.google.com') !== -1;
      html += '<div style="position:relative;width:100%;max-width:420px;padding-bottom:min(236px,56.25%);background:#000;border-radius:8px;overflow:hidden;margin-bottom:10px;">';
      if (_isWebm) {
        html += '<video src="' + _lsaEsc(_pUrl) + '" style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;" controls preload="metadata"></video>';
      } else if (_isDrive) {
        var _driveView = _pUrl.replace('/preview', '/view');
        html += '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#1e293b;">' +
          '<div style="font-size:48px;margin-bottom:8px;">📁</div>' +
          '<div style="color:#94a3b8;font-size:13px;margin-bottom:12px;">Grabación en Google Drive</div>' +
          '<a href="' + _lsaEsc(_driveView) + '" target="_blank" rel="noopener" style="background:#3b82f6;color:#fff;padding:8px 20px;border-radius:8px;text-decoration:none;font-size:13px;font-weight:600;">▶ Abrir en Drive</a>' +
        '</div>';
      } else {
        html += '<iframe src="' + _lsaEsc(_pUrl) + '" style="position:absolute;inset:0;width:100%;height:100%;border:none;" allow="accelerometer;gyroscope;autoplay;encrypted-media;picture-in-picture;fullscreen" allowfullscreen></iframe>';
      }
      html += '</div>';
    }

    // Info row
    html += '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:8px;">' +
      '<span style="color:#94a3b8;font-size:12px;">⏱ ' + dur + '</span>' +
      '<span style="color:#94a3b8;font-size:12px;">📅 ' + date + '</span>' +
      visBadge + freeBadge + processingBadge + transcriptBadge + quizBadge +
    '</div>';

    // Action buttons
    html += '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">';

    // Publish / Hide
    if (r.visible) {
      html += '<button class="lsa-btn lsa-btn-gray" onclick="lsaToggleRecordingVisibility(\'' + r.id + '\',false,\'' + streamId + '\')" style="font-size:11px;">👁‍🗨 Ocultar</button>';
    } else {
      html += '<button class="lsa-btn lsa-btn-green" onclick="lsaToggleRecordingVisibility(\'' + r.id + '\',true,\'' + streamId + '\')" style="font-size:11px;">✅ Publicar</button>';
    }

    // Free / Members-only
    if (r.is_free) {
      html += '<button class="lsa-btn" onclick="lsaToggleRecordingFree(\'' + r.id + '\',false,\'' + streamId + '\')" style="font-size:11px;background:#eab308;color:#000;">🔒 Solo Membresía</button>';
    } else {
      html += '<button class="lsa-btn" onclick="lsaToggleRecordingFree(\'' + r.id + '\',true,\'' + streamId + '\')" style="font-size:11px;background:#22c55e;color:#fff;">🆓 Gratis</button>';
    }

    // Download
    html += '<button class="lsa-btn lsa-btn-blue" onclick="lsaDownloadRecording(\'' + r.id + '\',\'' + (r.cf_video_uid || '') + '\')" style="font-size:11px;">⬇ Descargar</button>';

    // Trim (only for ready videos)
    if (r.status === 'ready' && r.cf_video_uid) {
      html += '<button class="lsa-btn" onclick="lsaShowTrimPanel(\'' + r.id + '\',\'' + (r.cf_video_uid || '') + '\',\'' + streamId + '\',' + (r.duration_seconds || 0) + ',\'' + _lsaEscJs(r.playback_url || '') + '\')" style="font-size:11px;background:#f97316;color:#fff;">✂ Recortar</button>';
    }

    // Transcribe
    if (!r.transcript) {
      html += '<button class="lsa-btn" onclick="lsaTranscribeRecording(\'' + r.id + '\',\'' + (r.cf_video_uid || '') + '\',\'' + streamId + '\')" style="font-size:11px;background:#8b5cf6;color:#fff;">🎙 Transcribir</button>';
    } else {
      html += '<button class="lsa-btn" onclick="lsaToggleTranscriptPreview(\'' + r.id + '\')" style="font-size:11px;background:#6d28d9;color:#fff;">📄 Ver Transcripción</button>';
    }

    // Generate Quiz (only if transcript exists)
    if (r.transcript && !r.quiz_questions) {
      html += '<button class="lsa-btn" onclick="lsaGenerateRecordingQuiz(\'' + r.id + '\',\'' + streamId + '\')" style="font-size:11px;background:#0ea5e9;color:#fff;">🤖 Generar Quiz</button>';
    } else if (r.quiz_questions) {
      var qCount = Array.isArray(r.quiz_questions) ? r.quiz_questions.length : 0;
      html += '<span style="color:#60a5fa;font-size:11px;font-weight:600;">📝 ' + qCount + ' preguntas</span>';
    }

    // Delete
    html += '<button class="lsa-btn lsa-btn-red" onclick="lsaDeleteRecording(\'' + r.id + '\',\'' + (r.cf_video_uid || '') + '\',\'' + streamId + '\')" style="font-size:11px;">🗑 Eliminar</button>';

    html += '</div>';

    // Status div for progress
    html += '<div id="lsaRecStatus_' + r.id + '" style="color:#94a3b8;font-size:12px;margin-top:6px;display:none;"></div>';

    // Transcript preview (hidden)
    if (r.transcript) {
      html += '<div id="lsaTranscript_' + r.id + '" style="display:none;margin-top:8px;background:#0f172a;border:1px solid rgba(255,255,255,0.1);border-radius:8px;padding:10px;max-height:200px;overflow-y:auto;font-size:12px;color:#cbd5e1;white-space:pre-wrap;">' +
        _lsaEsc(r.transcript) + '</div>';
    }

    html += '</div>';
  }

  panel.innerHTML = html;
  targetCard.after(panel);
}

/* ── Status helper ──────────────────────────────────────────── */
function _lsaRecStatus(recId, msg, color) {
  var el = document.getElementById('lsaRecStatus_' + recId);
  if (!el) return;
  el.style.display = msg ? '' : 'none';
  el.style.color = color || '#94a3b8';
  el.textContent = msg;
}

/* ── Toggle visibility ──────────────────────────────────────── */
async function lsaToggleRecordingVisibility(recId, visible, streamId) {
  _lsaRecStatus(recId, visible ? 'Publicando...' : 'Ocultando...', '#fbbf24');
  try {
    var { data, error } = await _cfStreamCall({ action: 'update_recording', recording_id: recId, updates: { visible: visible } });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    _lsaRecStatus(recId, '');
    lsaLoadRecordingsForStream(streamId);
  } catch (e) {
    _lsaRecStatus(recId, 'Error: ' + (e.message || e), '#ef4444');
  }
}

/* ── Toggle free ────────────────────────────────────────────── */
async function lsaToggleRecordingFree(recId, isFree, streamId) {
  _lsaRecStatus(recId, 'Actualizando...', '#fbbf24');
  try {
    var { data, error } = await _cfStreamCall({ action: 'update_recording', recording_id: recId, updates: { is_free: isFree } });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    _lsaRecStatus(recId, '');
    lsaLoadRecordingsForStream(streamId);
  } catch (e) {
    _lsaRecStatus(recId, 'Error: ' + (e.message || e), '#ef4444');
  }
}

/* ── Download recording ─────────────────────────────────────── */
async function lsaDownloadRecording(recId, cfUid) {
  _lsaRecStatus(recId, 'Obteniendo link de descarga...', '#3b82f6');
  try {
    var { data, error } = await _cfStreamCall({ action: 'get_download_url', recording_id: recId, cf_video_uid: cfUid });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    if (!data.download_url) throw new Error('No download URL returned');
    _lsaRecStatus(recId, '');
    window.open(data.download_url, '_blank');
  } catch (e) {
    _lsaRecStatus(recId, 'Error descarga: ' + (e.message || e), '#ef4444');
  }
}

/* ── Delete recording ───────────────────────────────────────── */
async function lsaDeleteRecording(recId, cfUid, streamId) {
  if (!confirm(_t('adm_lsa_confirm_delete_rec'))) return;
  var deleteFromCF = confirm(_t('adm_lsa_delete_from_cf'));

  _lsaRecStatus(recId, 'Eliminando...', '#ef4444');
  try {
    var { data, error } = await _cfStreamCall({ action: 'delete_recording', recording_id: recId, cf_video_uid: cfUid, delete_from_cf: deleteFromCF });
    if (error) throw error;
    if (data.error) throw new Error(data.error);
    lsaLoadRecordingsForStream(streamId);
  } catch (e) {
    _lsaRecStatus(recId, 'Error eliminando: ' + (e.message || e), '#ef4444');
  }
}

/* ── Transcribe recording ───────────────────────────────────── */
async function lsaTranscribeRecording(recId, cfUid, streamId) {
  _lsaRecStatus(recId, '⏳ Obteniendo video para transcribir...', '#8b5cf6');
  try {
    // Step 1: Get download URL
    var { data: dlData, error: dlErr } = await _cfStreamCall({ action: 'get_download_url', recording_id: recId, cf_video_uid: cfUid });
    if (dlErr) throw dlErr;
    if (dlData.error) throw new Error(dlData.error);
    if (!dlData.download_url) throw new Error('No download URL');

    // Step 2: Send URL to Deepgram via Edge Function
    _lsaRecStatus(recId, '🤖 Transcribiendo con Deepgram AI (30-60 seg)...', '#8b5cf6');
    var tRes = await fetch(_LSA_TRANSCRIBE_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (SUPABASE_KEY), 'x-admin-email': getAdminEmail() },
      body: JSON.stringify({ video_url: dlData.download_url, language: 'es' })
    });
    if (!tRes.ok) {
      var errData = {};
      try { errData = await tRes.json(); } catch(e) { console.warn('[LiveStreamAdmin]', e.message || e); }
      throw new Error(errData.error || 'Error de transcripción: ' + tRes.status);
    }
    var tData = await tRes.json();
    if (tData.error) throw new Error(tData.error);
    var transcriptText = (tData.text || '').trim();
    if (!transcriptText) throw new Error('La transcripción resultó vacía');

    // Step 3: Save transcript
    _lsaRecStatus(recId, '⏳ Guardando transcripción...', '#8b5cf6');
    var { data: upData, error: upErr } = await _cfStreamCall({ action: 'update_recording', recording_id: recId, updates: { transcript: transcriptText } });
    if (upErr) throw upErr;
    if (upData.error) throw new Error(upData.error);

    _lsaRecStatus(recId, '✅ Transcripción guardada — ' + transcriptText.split(/\s+/).length + ' palabras', '#22c55e');
    setTimeout(function() { lsaLoadRecordingsForStream(streamId); }, 1000);

  } catch (e) {
    _lsaRecStatus(recId, 'Error transcribiendo: ' + (e.message || e), '#ef4444');
  }
}

/* ── Generate quiz from transcript ──────────────────────────── */
async function lsaGenerateRecordingQuiz(recId, streamId) {
  try {
    // Get recording with transcript
    var { data: rec, error: recErr } = await supabaseClient
      .from('stream_recordings')
      .select('transcript, duration_seconds')
      .eq('id', recId)
      .single();

    if (recErr || !rec) { alert('Error cargando grabación'); return; }
    if (!rec.transcript || rec.transcript.length < 100) {
      alert('La grabación necesita una transcripción de al menos 100 caracteres.');
      return;
    }

    _lsaRecStatus(recId, '⏳ Generando quiz con IA...', '#0ea5e9');
    var dur = rec.duration_seconds || 600;
    var numQuestions = Math.max(3, Math.min(15, Math.round(dur / 120)));

    var systemPrompt = 'Eres un experto creador de quizzes educativos para técnicos de HVAC. ' +
      'Genera preguntas de opción múltiple basadas ESTRICTAMENTE en el contenido de la transcripción proporcionada. ' +
      'Cada pregunta debe evaluar comprensión real del material de la clase. ' +
      'Responde ÚNICAMENTE con un JSON array válido (sin markdown, sin explicación extra). ' +
      'Formato exacto de cada objeto: ' +
      '{"question":"texto de la pregunta","options":["A","B","C","D"],"correct":0,"explanation":"por qué es correcta","category":"tema"}. ' +
      'El campo "correct" es el índice (0-3) de la opción correcta. ' +
      'Las opciones incorrectas deben ser plausibles pero claramente incorrectas para quien estudió el material. ' +
      'Responde siempre en español.';

    var userMessage = 'Genera exactamente ' + numQuestions + ' preguntas de quiz basadas en esta transcripción de clase en vivo:\n\n' +
      '--- TRANSCRIPCIÓN ---\n' + rec.transcript.substring(0, 8000) + '\n--- FIN ---\n\n' +
      'Recuerda: responde SOLO con el JSON array, sin markdown ni texto adicional.';

    var response = await fetch(_LSA_AI_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (SUPABASE_KEY) },
      body: JSON.stringify({
        messages: [{ role: 'user', content: userMessage }],
        system: systemPrompt,
        max_tokens: 4000,
        admin_email: getAdminEmail()
      })
    });

    if (!response.ok) throw new Error('Error de IA: ' + response.status);

    var data = await response.json();
    var aiText = '';
    if (data.reply) aiText = data.reply;
    else if (data.content && typeof data.content === 'string') aiText = data.content;
    else if (data.content && Array.isArray(data.content)) aiText = data.content.map(function(b) { return b.text || ''; }).join('');
    else if (data.choices && data.choices[0]) aiText = data.choices[0].message ? data.choices[0].message.content : (data.choices[0].text || '');
    else if (typeof data === 'string') aiText = data;
    else aiText = JSON.stringify(data);

    aiText = aiText.replace(/^```json?\s*/i, '').replace(/\s*```$/i, '').trim();

    var jsonMatch = aiText.match(/\[[\s\S]*\]/);
    if (!jsonMatch) throw new Error('La IA no devolvió un JSON válido.');

    var questions = JSON.parse(jsonMatch[0]);
    if (!Array.isArray(questions) || questions.length === 0) throw new Error('No se generaron preguntas.');

    questions = questions.filter(function(q) {
      return q.question && Array.isArray(q.options) && q.options.length >= 3 && typeof q.correct === 'number';
    }).map(function(q) {
      return {
        question: q.question,
        options: q.options.slice(0, 4),
        correct: Math.min(q.correct, q.options.length - 1),
        explanation: q.explanation || '',
        category: q.category || ''
      };
    });

    if (questions.length === 0) throw new Error('Ninguna pregunta pasó la validación.');

    // Save quiz
    var { data: upData, error: upErr } = await _cfStreamCall({ action: 'update_recording', recording_id: recId, updates: { quiz_questions: questions } });
    if (upErr) throw upErr;
    if (upData.error) throw new Error(upData.error);

    _lsaRecStatus(recId, '✅ Quiz generado: ' + questions.length + ' preguntas', '#22c55e');
    setTimeout(function() { lsaLoadRecordingsForStream(streamId); }, 1000);

  } catch (e) {
    _lsaRecStatus(recId, 'Error generando quiz: ' + (e.message || e), '#ef4444');
  }
}

