          _lsaHmsConnected = false;
          var statusEl = document.getElementById('lsaBrowserStatus');
          if (statusEl) statusEl.innerHTML = '<span style="color:#ef4444;font-weight:700;">⚠️ Desconectado de 100ms — reconectando...</span>';
          // Attempt reconnect with exponential backoff
