var _lsaMsSelectedPlatform = null;

function lsaMsSelectPlatform(platformId) {
  _lsaMsSelectedPlatform = platformId;
  var p = _lsaPlatformInfo(platformId);
  var form = document.getElementById('lsaMsForm');
  var title = document.getElementById('lsaMsFormTitle');
  var nameInput = document.getElementById('lsaMsName');
  var urlInput = document.getElementById('lsaMsUrl');
  var keyInput = document.getElementById('lsaMsKey');

  if (form) form.style.display = '';
  if (title) title.innerHTML = p.icon + ' Conectar ' + p.name;
  if (nameInput) nameInput.value = p.name;
  if (urlInput) {
    urlInput.value = p.rtmpUrl;
    urlInput.readOnly = platformId !== 'custom';
    urlInput.style.opacity = platformId !== 'custom' ? '0.7' : '1';
  }
  if (keyInput) { keyInput.value = ''; keyInput.type = 'password'; keyInput.focus(); }
}

async function lsaMsSaveDestination() {
  var nameInput = document.getElementById('lsaMsName');
  var urlInput = document.getElementById('lsaMsUrl');
  var keyInput = document.getElementById('lsaMsKey');
  var statusEl = document.getElementById('lsaMsStatus');
  var saveBtn = document.getElementById('lsaMsSaveBtn');

  var name = nameInput ? nameInput.value.trim() : '';
  var url = urlInput ? urlInput.value.trim() : '';
  var key = keyInput ? keyInput.value.trim() : '';

  if (!name || !url || !key) {
    if (statusEl) { statusEl.textContent = 'Todos los campos son requeridos'; statusEl.style.color = '#ef4444'; }
    return;
  }

  if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Guardando...'; }

  try {
    var { error } = await supabaseClient.from('multistream_destinations').insert({
      platform: _lsaMsSelectedPlatform || 'custom',
      platform_name: name,
      rtmp_url: url,
      stream_key: key,
      enabled: true
    });

    if (error) throw error;

    if (statusEl) { statusEl.textContent = '¡Guardado!'; statusEl.style.color = '#22c55e'; }
    setTimeout(function() {
      var form = document.getElementById('lsaMsForm');
      if (form) form.style.display = 'none';
      if (statusEl) statusEl.textContent = '';
    }, 1000);

    lsaMsLoadDestinations();

  } catch(e) {
    console.error('[Multistream] Save error:', e);
    if (statusEl) { statusEl.textContent = 'Error: ' + (e.message || ''); statusEl.style.color = '#ef4444'; }
  } finally {
    if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Guardar Destino'; }
  }
}

async function lsaMsLoadDestinations() {
  var listEl = document.getElementById('lsaMsDestList');
  if (!listEl) return;

  try {
    var { data, error } = await supabaseClient
      .from('multistream_destinations')
      .select('*')
      .order('created_at', { ascending: true });

    if (error) throw error;

    if (!data || data.length === 0) {
      listEl.innerHTML = '<div style="text-align:center;padding:20px;color:#64748b;font-size:13px;">No tienes destinos configurados.<br>Agrega tu primera red social arriba.</div>';
      return;
    }

    var html = '';
    for (var i = 0; i < data.length; i++) {
      var d = data[i];
      var p = _lsaPlatformInfo(d.platform);
      var enabled = d.enabled;
      var maskedKey = d.stream_key ? '••••••' + d.stream_key.slice(-4) : '••••';

      html += '<div style="display:flex;align-items:center;gap:10px;padding:12px 14px;background:#0f172a;border-radius:10px;margin-bottom:6px;border:1px solid ' + p.color + '33;">' +
        '<span style="font-size:24px;">' + p.icon + '</span>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="color:' + p.color + ';font-weight:600;font-size:13px;">' + _lsaEsc(d.platform_name) + '</div>' +
          '<div style="color:#64748b;font-size:10px;">Key: ' + maskedKey + '</div>' +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:6px;">' +
          // Toggle enabled/disabled
          '<button onclick="lsaMsToggle(\'' + d.id + '\',' + !enabled + ')" style="background:' + (enabled ? '#22c55e22' : '#64748b22') + ';border:1px solid ' + (enabled ? '#22c55e44' : '#64748b44') + ';color:' + (enabled ? '#22c55e' : '#64748b') + ';padding:4px 10px;border-radius:6px;cursor:pointer;font-size:10px;font-weight:600;">' + (enabled ? 'ON' : 'OFF') + '</button>' +
          '<button onclick="lsaMsDelete(\'' + d.id + '\')" style="background:#ef444422;border:1px solid #ef444444;color:#ef4444;padding:4px 8px;border-radius:6px;cursor:pointer;font-size:10px;font-weight:600;">🗑</button>' +
        '</div>' +
      '</div>';
    }

    listEl.innerHTML = html;

  } catch(e) {
    console.error('[Multistream] Load error:', e);
    listEl.innerHTML = '<div style="color:#ef4444;">Error cargando destinos</div>';
  }
}

async function lsaMsToggle(destId, enabled) {
  try {
    await supabaseClient.from('multistream_destinations').update({ enabled: enabled }).eq('id', destId);
    lsaMsLoadDestinations();
  } catch(e) { console.error('[Multistream] Toggle error:', e); }
}

async function lsaMsDelete(destId) {
  if (!confirm(_t('adm_lsa_confirm_delete_dest'))) return;
  try {
    await supabaseClient.from('multistream_destinations').delete().eq('id', destId);
    lsaMsLoadDestinations();
  } catch(e) { console.error('[Multistream] Delete error:', e); }
}

async function lsaSyncPermanentOutputsFromModal() {
  var statusEl = document.getElementById('lsaMsSyncStatus');
  if (statusEl) { statusEl.textContent = _t('adm_lsa_syncing'); statusEl.style.color = '#f97316'; }

  try {
    var { data, error } = await _cfStreamCall({ action: 'sync_permanent_outputs' });
    if (error) throw error;
    if (data.error) throw new Error(data.error);

    var msg = '';
    if (data.added && data.added.length > 0) msg += _t('adm_lsa_added') + ': ' + data.added.join(', ') + '. ';
    if (data.removed && data.removed.length > 0) msg += _t('adm_lsa_removed') + ': ' + data.removed.length + '. ';
    if (!msg) msg = _t('adm_lsa_all_synced') + ' — ' + (data.total_active || 0) + ' ' + _t('adm_lsa_active_dest') + '.';

    if (statusEl) { statusEl.textContent = msg; statusEl.style.color = '#22c55e'; }
  } catch (e) {
    console.error('[Multistream] Sync error:', e);
    if (statusEl) { statusEl.textContent = 'Error: ' + (e.message || e); statusEl.style.color = '#ef4444'; }
  }
}

/* ===================================================================
   Waiting Room — Admin Side (Sala de Espera)
   Uses Supabase Realtime Presence to see students waiting for approval.
   =================================================================== */
var _lsaWrChannels = {};   // { streamId: channel }
var _lsaWrStudents = {};   // { streamId: { email: { nombre, telefono, requested_at } } }

function lsaWrSubscribe(streamId) {
  if (_lsaWrChannels[streamId]) return; // already subscribed

  _lsaWrStudents[streamId] = {};
  var channelName = 'waiting-room-' + streamId;
  console.log('[WR-Admin] Subscribing to channel:', channelName, 'for stream:', streamId);

  var channel = supabaseClient.channel(channelName);

  channel
    .on('presence', { event: 'sync' }, function() {
      var state = channel.presenceState();
      console.log('[WR-Admin] SYNC event — presenceState:', JSON.stringify(state));
      _lsaWrStudents[streamId] = {};
      for (var key in state) {
        if (state[key] && state[key][0]) {
          _lsaWrStudents[streamId][key] = state[key][0];
        }
      }
      var count = Object.keys(_lsaWrStudents[streamId]).length;
      console.log('[WR-Admin] Students after sync:', count);
      _lsaWrUpdateCount(streamId);
      _lsaWrRenderList(streamId);
    })
    .on('presence', { event: 'join' }, function(payload) {
      console.log('[WR-Admin] JOIN event — key:', payload.key, 'data:', JSON.stringify(payload.newPresences));
      var key = payload.key;
      if (payload.newPresences && payload.newPresences[0]) {
        _lsaWrStudents[streamId][key] = payload.newPresences[0];
      }
      _lsaWrUpdateCount(streamId);
      _lsaWrRenderList(streamId);
      _lsaWrNotifyNew(payload.newPresences ? payload.newPresences[0] : null);
    })
    .on('presence', { event: 'leave' }, function(payload) {
      console.log('[WR-Admin] LEAVE event — key:', payload.key);
      delete _lsaWrStudents[streamId][payload.key];
      _lsaWrUpdateCount(streamId);
      _lsaWrRenderList(streamId);
    })
    .subscribe(function(status) {
      console.log('[WR-Admin] Channel subscription status:', status);
    });

  _lsaWrChannels[streamId] = channel;
}

function _lsaWrUpdateCount(streamId) {
  var countEl = document.getElementById('lsaWrCount_' + streamId);
  var students = _lsaWrStudents[streamId] || {};
  var count = Object.keys(students).length;
  if (countEl) {
    countEl.textContent = count > 0 ? '(' + count + ')' : '';
  }
  var btn = document.getElementById('lsaWrBtn_' + streamId);
  if (btn) {
    btn.style.animation = count > 0 ? 'lsa-pulse 1s infinite' : '';
    btn.style.background = count > 0 ? '#ef4444' : '#f59e0b';
  }
  // Also update badge on browser streaming control bar
  var badge = document.getElementById('lsaWrBadge');
  var wrBtn = document.getElementById('lsaBtnWaitingRoom');
  if (badge) {
    if (count > 0) {
      badge.textContent = count;
      badge.style.display = '';
    } else {
      badge.style.display = 'none';
    }
  }
  if (wrBtn) {
    wrBtn.style.animation = count > 0 ? 'lsa-pulse 1s infinite' : '';
    wrBtn.style.background = count > 0 ? '#ef4444' : '#f59e0b';
  }
}

function _lsaWrNotifyNew(presence) {
  if (!presence) return;
  if (navigator.vibrate) navigator.vibrate([200, 100, 200]);

  // Audio beep so admin doesn't miss students waiting
  try {
    var ac = new (window.AudioContext || window.webkitAudioContext)();
    ac.resume().catch(function(){});
    var osc = ac.createOscillator();
    var gain = ac.createGain();
    osc.type = 'sine';
    osc.frequency.value = 880;
    gain.gain.value = 0.3;
    osc.connect(gain);
    gain.connect(ac.destination);
    osc.start();
    osc.stop(ac.currentTime + 0.15);
    setTimeout(function() {
      var osc2 = ac.createOscillator();
      var gain2 = ac.createGain();
      osc2.type = 'sine';
      osc2.frequency.value = 1100;
      gain2.gain.value = 0.3;
      osc2.connect(gain2);
      gain2.connect(ac.destination);
      osc2.start();
      osc2.stop(ac.currentTime + 0.2);
      // Close AudioContext after beep to prevent resource leak
      setTimeout(function() { try { ac.close(); } catch(e2) { console.warn('[LiveStreamAdmin]', e2.message || e2); } }, 500);
    }, 200);
  } catch(e) { console.warn('[LiveStreamAdmin]', e.message || e); }

  // Toast notification
  var nombre = presence.nombre || presence.email || 'Estudiante';
  var toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;top:20px;right:20px;z-index:999999;background:linear-gradient(135deg,#f59e0b,#d97706);color:#fff;padding:14px 20px;border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,0.4);font-size:14px;font-weight:700;animation:lsa-slideIn 0.3s ease;max-width:320px;';
  toast.innerHTML = '<b>' + _lsaEsc(nombre) + '</b> ' + _t('adm_lsa_in_waiting_room');
  document.body.appendChild(toast);
  setTimeout(function() {
    toast.style.opacity = '0';
    toast.style.transition = 'opacity 0.5s';
    setTimeout(function() { toast.remove(); }, 500);
  }, 5000);
}

function lsaWrShowRoom(streamId) {
  lsaWrSubscribe(streamId);

  var existing = document.getElementById('lsaWrModal');
  if (existing) existing.remove();

  var modal = document.createElement('div');
  modal.id = 'lsaWrModal';
  modal.className = 'lsa-modal-overlay';
  modal.setAttribute('data-stream-id', streamId);
  modal.innerHTML =
    '<div class="lsa-modal" style="max-width:550px;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">' +
        '<div style="display:flex;align-items:center;gap:10px;">' +
          '<span style="font-size:24px;">\uD83D\uDEAA</span>' +
          '<div>' +
            '<div style="color:#e2e8f0;font-weight:800;font-size:18px;">' + _t('adm_lsa_waiting_room') + '</div>' +
            '<div style="color:#64748b;font-size:11px;">' + _t('adm_lsa_waiting_approval') + '</div>' +
          '</div>' +
        '</div>' +
        '<button onclick="document.getElementById(\'lsaWrModal\').remove()" style="background:none;border:none;color:#94a3b8;font-size:24px;cursor:pointer;">\u2715</button>' +
      '</div>' +
      '<div style="display:flex;gap:8px;margin-bottom:14px;">' +
        '<button class="lsa-btn lsa-btn-green" onclick="lsaWrApproveAll(\'' + streamId + '\')">\u2705 ' + _t('adm_lsa_approve_all') + '</button>' +
        '<button class="lsa-btn lsa-btn-red" onclick="lsaWrRejectAll(\'' + streamId + '\')">\uD83D\uDEAB ' + _t('adm_lsa_reject_all') + '</button>' +
      '</div>' +
      '<div id="lsaWrList" style="max-height:400px;overflow-y:auto;">' +
        '<div style="text-align:center;padding:20px;color:#64748b;">Cargando...</div>' +
      '</div>' +
    '</div>';

  document.body.appendChild(modal);
  _lsaWrRenderList(streamId);
}

function _lsaWrRenderList(streamId) {
  var listEl = document.getElementById('lsaWrList');
  if (!listEl) return;

  // Make sure we're rendering for the right stream
  var modal = document.getElementById('lsaWrModal');
  if (modal && modal.getAttribute('data-stream-id') !== streamId) return;

  var students = _lsaWrStudents[streamId] || {};
  var entries = Object.keys(students);

  if (entries.length === 0) {
    listEl.innerHTML =
      '<div style="text-align:center;padding:30px;">' +
        '<div style="font-size:36px;margin-bottom:8px;">\u2728</div>' +
        '<div style="color:#64748b;font-size:13px;">No hay estudiantes esperando</div>' +
      '</div>';
    return;
  }

  var html = '';
  for (var i = 0; i < entries.length; i++) {
    var email = entries[i];
    var s = students[email];
    var name = s.nombre || email;
    var phone = s.telefono || '';
    var photo = s.photo || '';
    var time = s.requested_at ? new Date(s.requested_at).toLocaleTimeString('es-US', { hour: '2-digit', minute: '2-digit' }) : '';
    var initial = (name.charAt(0) || '?').toUpperCase();
    var safeEmail = email.replace(/'/g, "\\'");

    // Photo or initial avatar — validate URL to prevent javascript: XSS
    var safePhoto = '';
    if (photo && /^https?:\/\//i.test(photo)) safePhoto = photo;
    var avatarHtml = safePhoto
      ? '<img src="' + _lsaEsc(safePhoto) + '" style="width:50px;height:50px;border-radius:50%;object-fit:cover;flex-shrink:0;border:2px solid rgba(14,165,233,0.5);">'
      : '<div style="width:50px;height:50px;background:linear-gradient(135deg,#3b82f6,#1d4ed8);border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:17px;flex-shrink:0;">' + initial + '</div>';

    html +=
      '<div style="display:flex;align-items:center;gap:12px;padding:12px;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:10px;margin-bottom:8px;">' +
        avatarHtml +
        '<div style="flex:1;min-width:0;">' +
          '<div style="color:#e2e8f0;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + _lsaEsc(name) + '</div>' +
          '<div style="color:#64748b;font-size:11px;">' + _lsaEsc(email) + (phone ? ' \u00B7 ' + _lsaEsc(phone) : '') + '</div>' +
          (time ? '<div style="color:#475569;font-size:10px;">Solicit\u00F3: ' + time + '</div>' : '') +
        '</div>' +
        '<div style="display:flex;gap:6px;flex-shrink:0;">' +
          '<button onclick="lsaWrApprove(\'' + streamId + '\',\'' + safeEmail + '\')" class="lsa-btn lsa-btn-green" style="padding:8px 14px;font-size:13px;" title="Aprobar">\u2705</button>' +
          '<button onclick="lsaWrReject(\'' + streamId + '\',\'' + safeEmail + '\')" class="lsa-btn lsa-btn-red" style="padding:8px 14px;font-size:13px;" title="Rechazar">\uD83D\uDEAB</button>' +
        '</div>' +
      '</div>';
  }

  listEl.innerHTML = html;
}

function lsaWrApprove(streamId, email) {
  var channel = _lsaWrChannels[streamId];
  if (!channel) return;
  channel.send({
    type: 'broadcast',
    event: 'admission',
    payload: { action: 'approve', email: email }
  });
  if (_lsaWrStudents[streamId]) {
    delete _lsaWrStudents[streamId][email];
    _lsaWrUpdateCount(streamId);
    _lsaWrRenderList(streamId);
  }
}

function lsaWrReject(streamId, email) {
  var channel = _lsaWrChannels[streamId];
  if (!channel) return;
  channel.send({
    type: 'broadcast',
    event: 'admission',
    payload: { action: 'reject', email: email }
  });
  if (_lsaWrStudents[streamId]) {
    delete _lsaWrStudents[streamId][email];
    _lsaWrUpdateCount(streamId);
    _lsaWrRenderList(streamId);
  }
}

function lsaWrApproveAll(streamId) {
  var students = _lsaWrStudents[streamId] || {};
  var emails = Object.keys(students);
  for (var i = 0; i < emails.length; i++) {
    lsaWrApprove(streamId, emails[i]);
  }
}

function lsaWrRejectAll(streamId) {
  var students = _lsaWrStudents[streamId] || {};
  var emails = Object.keys(students);
  for (var i = 0; i < emails.length; i++) {
    lsaWrReject(streamId, emails[i]);
  }
}
